/**
 * Finnish (Suomi) language functions
 *
 * @author Santhosh Thottingal
 */

( function ( $ ) {
	'use strict';

	$.i18n.languages.fi = $.extend( {}, $.i18n.languages[ 'default' ], {
		convertGrammar: function ( word, form ) {
			// vowel harmony flag
			var aou = word.match( /[aou][^äöy]*$/i ),
				origWord = word;
			if ( word.match( /wiki$/i ) ) {
				aou = false;
			}

			// append i after final consonant
			if ( word.match( /[bcdfghjklmnpqrstvwxz]$/i ) ) {
				word += 'i';
			}

			switch ( form ) {
				case 'genitive':
					word += 'n';
					break;
				case 'elative':
					word += ( aou ? 'sta' : 'stä' );
					break;
				case 'partitive':
					word += ( aou ? 'a' : 'ä' );
					break;
				case 'illative':
				// Double the last letter and add 'n'
					word += word.slice( -1 ) + 'n';
					break;
				case 'inessive':
					word += ( aou ? 'ssa' : 'ssä' );
					break;
				default:
					word = origWord;
					break;
			}

			return word;
		}
	} );
}( jQuery ) );


/* ===== /3rdparty/jquery.i18n/languages/ru.js ===== */

/**
 * Russian (Русский) language functions
 */

( function ( $ ) {
	'use strict';

	$.i18n.languages.ru = $.extend( {}, $.i18n.languages[ 'default' ], {
		convertGrammar: function ( word, form ) {
			if ( form === 'genitive' ) { // родительный падеж
				if ( word.slice( -1 ) === 'ь' ) {
					word = word.slice( 0, -1 ) + 'я';
				} else if ( word.slice( -2 ) === 'ия' ) {
					word = word.slice( 0, -2 ) + 'ии';
				} else if ( word.slice( -2 ) === 'ка' ) {
					word = word.slice( 0, -2 ) + 'ки';
				} else if ( word.slice( -2 ) === 'ти' ) {
					word = word.slice( 0, -2 ) + 'тей';
				} else if ( word.slice( -2 ) === 'ды' ) {
					word = word.slice( 0, -2 ) + 'дов';
				} else if ( word.slice( -3 ) === 'ник' ) {
					word = word.slice( 0, -3 ) + 'ника';
				}
			}

			return word;
		}
	} );
}( jQuery ) );


