/* ===== /scripts/util/i18n.js ===== */

I18NUtil = {};

/*
 * Initialize i18n and load message translation file for
 * the given module.
 * @public
 * @param {string} module The module name to load the translation file for.
 */
I18NUtil.init = function (module) {
    /*
     * Note that the browser language is only used to show a warning if the server
     * replies with another. The language is instead picked form the `userLang` preference.
     */
    var browserLang = (navigator.language || navigator.userLanguage || 'en');
    var lang = browserLang.split("-")[0];
    var dictionary = {}; // ensure object to avoid spurious network fetches

    $.ajax({
        url: "command/core/load-language?",
        type: "POST",
        async: false,
        data: {
            module: module
        },
        success: function (data) {
            if (data && data['dictionary']) { dictionary = data['dictionary']; }
            var langFromServer = data['lang'];
            if (lang !== langFromServer) {
                console.warn('Language \'' + lang + '\' missing translation. Defaulting to \''+langFromServer+'\'.');
                if (typeof langFromServer === 'string' && langFromServer.length) { lang = langFromServer; }
            }
        }
    }).fail(function( jqXhr, textStatus, errorThrown ) {
        var errorMessage = $.i18n ? $.i18n('core-index/prefs-loading-failed') : '';
        if (errorMessage && errorMessage != 'core-index/prefs-loading-failed') {
            alert(errorMessage);
        } else {
            // Non-blocking: log and continue with fallback
            console.warn("Failed to load language for module '" + module + "': " + textStatus + ':' + errorThrown);
        }
    });
    try {
        $.i18n().load(dictionary || {}, lang || 'en');
    } catch (e) {
        console.warn("i18n load failed, falling back to 'en':", e);
        try { $.i18n().load(dictionary || {}, 'en'); } catch (e2) {}
    }
    $('html').attr('lang', (lang || 'en').replace('_', '-'));
    if (module === 'core') {
      $.i18n({ locale: (lang || 'en') });
      // TODO: This should be globally accessible, but this is OK for our current needs
      Refine.userLang = (lang || 'en');
    }
}


/* ===== /scripts/util/csrf.js ===== */

CSRFUtil = {
    _tokenMaxAge: 30 * 60 * 1000 // half an hour in milliseconds (tokens live for 1 hour in the backend)
};


/**
 * Requests a CSRF token and calls the supplied callback.
 * @param {function(string)} onCSRF - The callback to call with the token.
 */
CSRFUtil.wrapCSRF = function(onCSRF) {
    let tokenAge = CSRFUtil._tokenMaxAge + 1;
    if (CSRFUtil._token && CSRFUtil._fetchedOn) {
        tokenAge = new Date() - CSRFUtil._fetchedOn;
    }
    if (tokenAge < CSRFUtil._tokenMaxAge) {
        onCSRF(CSRFUtil._token);
    } else {
        $.get(
            "command/core/get-csrf-token",
            {},
            function(response) {
                CSRFUtil._token = response['token'];
                CSRFUtil._fetchedOn = new Date();
                onCSRF(CSRFUtil._token);
            },
            "json"
        );
    }
};

/**
 * Performs a POST request where an additional CSRF token is automatically attached.
 * @param {string} url - The URL to send the request to.
 * @param {Object|string} data - The data to send with the request.
 * @param {function(object)} success - The callback to call on success.
 * @param {string} dataType - The type of data expected in the response.
 * @param {function(object)} failCallback - The callback to call on failure.
 * @returns {jQuery.jqXHR} The jQuery AJAX request object.
 */
CSRFUtil.postCSRF = function(url, data, success, dataType, failCallback) {
    CSRFUtil.wrapCSRF(function(token) {
        var fullData = data || {};
        if (typeof fullData == 'string') {
            fullData = fullData + "&" + $.param({csrf_token: token});
        } else {
            fullData['csrf_token'] = token;
        }
        var req = $.post(url, fullData, success, dataType);
        if (failCallback !== undefined) {
            req.fail(failCallback);
        }
    });
};


