  this._elmts.or_dialog_custom.html($.i18n('core-dialogs/custom'));
  this._elmts.or_dialog_help.html($.i18n('core-dialogs/help'));
  this._elmts.or_dialog_localTime.html($.i18n('core-dialogs/local-time'));
