// This file is added to the /project page

// Batch title extraction monitor: while an extraction task is running for the
// currently opened project, show a progress banner (with progress bar) and
// auto-refresh the data table as new rows are appended.

var BatchTitleExtractionMonitor = (function () {
  var POLL_INTERVAL = 2000;
  var FINAL_BANNER_MS = 10000;

  var pollTimer = null;
  var lastRowsAppended = -1;
  var $banner = null;
  var bannerHideTimer = null;
  var runningDismissed = null;
  var i18nReady = false;

  // localStorage记录按项目持久化"用户已关闭的终态横幅"：
  // 终态（完成/取消/失败）横幅一旦被用户关闭，刷新或重进项目页均不再出现；
  // 运行中关闭仅静默到下一次进度更新。
  function dismissedStorageKey(pid) {
    return 'files-batch-banner-dismissed-' + pid;
  }

  function isFinalStatus(status) {
    return status === 'completed' || status === 'cancelled' || status === 'failed';
  }

  function readDismissedFinal(pid) {
    try {
      return window.localStorage.getItem(dismissedStorageKey(pid));
    } catch (e) {
      return null;
    }
  }

  function writeDismissedFinal(pid, status) {
    try {
      window.localStorage.setItem(dismissedStorageKey(pid), status);
    } catch (e) {
      // ignore
    }
  }

  function clearDismissedFinal(pid) {
    try {
      window.localStorage.removeItem(dismissedStorageKey(pid));
    } catch (e) {
      // ignore
    }
  }

  function loadExtensionMessages() {
    try {
      if (window.I18NUtil && typeof I18NUtil.init === 'function') {
        I18NUtil.init('files');
      }
      i18nReady = true;
    } catch (e) {
      i18nReady = true;
    }
  }

  function getProjectId() {
    try {
      if (typeof theProject !== 'undefined' && theProject && typeof theProject.id !== 'undefined') {
        return theProject.id;
      }
      if (typeof project !== 'undefined' && project && typeof project.id !== 'undefined') {
        return project.id;
      }
    } catch (e) {
      // ignore
    }
    return null;
  }

  /** 表格「跟随最新」的容差（px）：距底不超过该值即视为用户正在看最新数据 */
  var FOLLOW_BOTTOM_TOLERANCE_PX = 80;

  /**
   * 用户本来就在底部附近时，把表格滚到最新一行；否则不动，尊重用户当前的浏览位置。
   */
  function followTableBottom() {
    var el = document.querySelector('.data-table-container');
    if (!el) return;
    if (el.scrollHeight - el.scrollTop - el.clientHeight <= FOLLOW_BOTTOM_TOLERANCE_PX) {
      el.scrollTop = el.scrollHeight;
    }
  }

  /**
   * 已展示条目的上限（与后端页级预览容量一致）：本卷已抽页全部保留，换卷时清空。
   * 此前与后端同为 40，导致重新进入项目页只剩最近 40 条、看不到本卷抽过的页；
   * 容器本身有竖向滚动，保留整卷不会撑破界面。
   */
  var PAGE_PREVIEW_MAX = 2000;
  /** 待揭示队列的上限：只作兜底，揭示节奏与抽取节奏大体匹配，正常不会触发 */
  var PAGE_PENDING_LIMIT = 2000;
  /** 后端还没测出平均耗时时的兜底揭示间隔 */
  var PAGE_REVEAL_FALLBACK_MS = 3000;
  /** 揭示间隔的上下限：太快等于一次性蹦出，太慢会一直追不上抽取进度 */
  var PAGE_REVEAL_MIN_MS = 800;
  var PAGE_REVEAL_MAX_MS = 8000;
  /**
   * 逐条揭示间隔（毫秒）：0 表示「到达即显示」。
   * 后端每批并发抽 4 页、同时返回，一次性弹出 4 条过于突兀，故按实测的平均每页耗时逐条揭示；
   * 逐页串行调用的门类（每页本身就是一条，3 秒左右一页）不需要这个节奏，直接显示即可。
   */
  var previewIntervalMs = 0;
  /** 已展示的页（按页号升序，最新在最下方）与待揭示队列 */
  var previewShown = [];
  var previewPending = [];
  /**
   * 已见过的页号。**必须独立于「已展示/待揭示」两个列表**：后端每轮返回的是最近 40 页的
   * 滚动窗口，而这两个列表都有 40 条上限（会从最旧一端淘汰），一旦靠它们去重，被淘汰过的页
   * 下一轮就会被当成新页重新塞回来——表现是清单乱序、同一页冒出来两次（跑过 40 页才现形）。
   * 页号在卷内单调递增，故这里只增不减，换卷时清空。
   */
  var previewKnown = {};
  var previewTimer = null;
  /** 预览所属的卷序号：换卷后页号会重新从 1 开始，必须重置队列，否则新旧卷的页会混在一起 */
  var previewVolumeIndex = -1;

  function resetPagePreview() {
    previewShown = [];
    previewPending = [];
    previewKnown = {};
    previewIntervalMs = 0;
    previewVolumeIndex = -1;
    if (previewTimer) {
      window.clearTimeout(previewTimer);
      previewTimer = null;
    }
  }

  /**
   * 按后端给的口径更新揭示间隔：并发批调用用实测的平均每页耗时，逐页串行用 0（到达即显示）。
   *
   * **只更新目标间隔，不动正在跑的定时器**：轮询每 2s 刷新一次平均每页耗时，若那点微小变化
   * 就重建定时器，会把当前这一轮的等待相位整段丢掉（间隔 800ms、轮询 2s 时每次轮询白丢
   * 近一轮等待），揭示速率掉到设计值的 1/2.5，观感就是「追不上」。相位改由
   * schedulePreviewTick 在**下一次排程**时读取新值。
   */
  function updatePreviewInterval(pageConcurrency, avgPageMillis) {
    if (pageConcurrency > 1) {
      previewIntervalMs = (typeof avgPageMillis === 'number' && avgPageMillis > 0)
          ? avgPageMillis : PAGE_REVEAL_FALLBACK_MS;
      previewIntervalMs = Math.max(PAGE_REVEAL_MIN_MS,
          Math.min(PAGE_REVEAL_MAX_MS, previewIntervalMs));
    } else {
      previewIntervalMs = 0;
    }
  }

  /**
   * 把一条按页号升序插入已展示列表。
   *
   * 并发批调用（后端 4 页同时返回）下"后到的页"页号可能比已展示的更小：被跳过的页
   * （分类器判跳/短文本短路）秒级返回，需走 LLM 的页要数秒——完成顺序与页号顺序不一致。
   * 只往末尾压就会出现「第 4 页、第 3 页、第 6 页、第 1 页…」这类乱序，故这里按页号就位。
   */
  function insertShown(p) {
    var i = previewShown.length;
    while (i > 0 && previewShown[i - 1].page > p.page) {
      i--;
    }
    previewShown.splice(i, 0, p);
  }

  /** 把积压队列按当前间隔揭示若干条；all 为真或间隔为 0 时一次揭完 */
  function revealPending(all) {
    var count = 1;
    if (all || previewIntervalMs <= 0) {
      count = previewPending.length;
    } else if (previewPending.length > 20) {
      // 积压追赶：队列越长一次揭示越多，避免预览永远追不上顶部的进度文案
      count = 4;
    } else if (previewPending.length > 8) {
      count = 2;
    }
    while (count-- > 0 && previewPending.length > 0) {
      insertShown(previewPending.shift());
      while (previewShown.length > PAGE_PREVIEW_MAX) {
        previewShown.shift();
      }
    }
  }

  /**
   * 自调度排一次揭示（setTimeout 链，不是 setInterval）。每次 tick 结束后按**当时**的
   * 目标间隔排下一次，因此轮询刷新间隔不会打断正在等待的这一轮。
   */
  function schedulePreviewTick($banner) {
    previewTimer = window.setTimeout(function () {
      previewTimer = null;
      if (previewPending.length === 0) {
        return;
      }
      revealPending(false);
      renderPagePreview($banner);
      if (previewPending.length > 0) {
        schedulePreviewTick($banner);
      }
    }, Math.max(1, previewIntervalMs));
  }

  /**
   * 把积压全部揭示出来，只在**转终态**时调用：终态横幅马上会被结果页（reinitializeProjectData
   * 重建项目 UI）顶掉，再按节奏逐条放就来不及了，最后那几条会永远看不到。故这里一次放完——
   * 是兜底，不是常规路径：页抽完进入 LLM 分件后没有新页到达，剩余几条按原节奏（0.8s/条）
   * 放得完，不必抢。
   */
  function flushPagePreview($banner) {
    if (previewTimer) {
      window.clearTimeout(previewTimer);
      previewTimer = null;
    }
    if (previewPending.length === 0) {
      return;
    }
    revealPending(true);
    renderPagePreview($banner);
  }

  /**
   * 接收后端页级预览并逐条揭示。
   *
   * 件级行要等整卷抽完、分件矫正后才写入，2-300 页的长卷会让界面长时间空白，故页级每抽完
   * 一页就回传一条。并发批调用（4 页同时返回）时排入队列、按实测的平均每页耗时逐条揭示，
   * 并**按页号就位**（不是压到末尾）：被跳过的页秒级返回、需走 LLM 的页要数秒，完成顺序与
   * 页号顺序并不一致，只往末尾压就会出现乱序。
   *
   * **首次到达的一批不重放**：进入项目时后端往往已经抽了几十页，那是「历史」而非"刚发生"。
   * 逐条重放会永远落后于实际进度（界面停在几十页前，看不到当下正在抽的页），故只接上
   * 最新一条，从那里往下长。
   */
  function feedPagePreview($banner, pages, volumeIndex) {
    if (volumeIndex !== previewVolumeIndex) {
      previewVolumeIndex = volumeIndex;
      previewShown = [];
      previewPending = [];
      previewKnown = {};
      $banner.find('.batch-extraction-banner-preview').remove();
    }
    var insertedHistorical = false;
    if (pages && pages.length > 0) {
      pages.forEach(function (p) {
        if (previewKnown[p.page]) return;
        previewKnown[p.page] = true;
        if (p.cached) {
          // 复用上次识别结果的历史页（续跑时前面若干页）：直接铺进已展示列表，不进揭示队列。
          // 它们毫秒级成批到达，若还按新页节奏（0.8-8s/条）揭示，几十上百页历史会一条条回放，
          // 界面永远追不上真实进度——这正是「重启后重进界面像在回放」的根因。
          insertShown(p);
          insertedHistorical = true;
        } else {
          previewPending.push(p);
        }
      });
      previewPending.sort(function (a, b) {
        return a.page - b.page;
      });
      while (previewPending.length > PAGE_PENDING_LIMIT) {
        previewPending.shift();
      }
      while (previewShown.length > PAGE_PREVIEW_MAX) {
        previewShown.shift();
      }
    }
    if (insertedHistorical) {
      // 历史页已整批铺好：立刻渲染，等队列节奏只会把它们也拖成「逐条揭示」
      renderPagePreview($banner);
    }
    // 首次（含换卷后第一次）：列表还空着，此刻到达的都是「进项目之前就抽完」的历史。
    // 一次性铺开、**不逐条重放**——重放会让预览永远落后于实际进度；但**也不能丢**：
    // 列表可往上翻，用户回头能看见这段时间认出了什么。只有后续新页才逐条揭示。
    if (previewShown.length === 0 && previewPending.length > 0 && previewIntervalMs > 0) {
      revealPending(true);
      renderPagePreview($banner);
      return;
    }
    // 逐页串行调用（间隔为 0）：每页到达本身就是一条，直接显示，不必排队等定时器
    if (previewIntervalMs <= 0) {
      if (previewPending.length > 0) {
        revealPending(true);
        renderPagePreview($banner);
      }
      return;
    }
    // 间隔变化后若那一轮恰好没有新页到达，这里负责把积压的队列重新驱动起来，
    // 否则预览会停在原地等下一页（长卷单页可达 20s，观感就是「卡住不动」）
    if (!previewTimer && previewPending.length > 0) {
      schedulePreviewTick($banner);
    }
  }

  /**
   * 预览列名兜底：key → i18n 键。列名正常由后端随 fields 一并返回；这里只在后端为
   * 旧版本（fields 仍是 {key: value}、没带列名）时把键译成中文，与导入对话框
   * （import-from-local-dir.js 的 FIXED/OPTIONAL/EXTRA_ELEMENTS）保持一致。
   */
  var PREVIEW_FIELD_I18N = {
    title: 'files-import/el-title',
    responsible_party: 'files-import/el-responsible',
    document_number: 'files-import/el-docno',
    date: 'files-import/el-date',
    miji: 'files-import/el-security',
    kaifang_zhuangtai: 'files-import/el-open-status',
    anyou: 'files-import/el-case-cause',
    dangshiren: 'files-import/el-party',
    shenji: 'files-import/el-trial-level',
    jiean_fangshi: 'files-import/el-closing-method',
    baoguan_qixian: 'files-import/el-retention'
  };

  function previewFieldLabel(key) {
    var i18nKey = PREVIEW_FIELD_I18N[key];
    if (i18nKey) {
      var label = $.i18n(i18nKey);
      if (label && label !== i18nKey) return label;
    }
    return key;
  }

  /**
   * 预览要素列表：后端返回 [{name, value}]；旧后端返回 {key: value}，一并兼容，
   * 避免前后端版本错配时整条预览抛异常。旧结构下列名未知的键不展示——AIMP 会随页级
   * 结果返回 party_roles 这类内部辅助数据（供分件用，不是著录项），显示出来只是原始 JSON。
   */
  function previewFieldList(fields) {
    if (!fields) return [];
    if (Array.isArray(fields)) return fields;
    if (typeof fields !== 'object') return [];
    var list = [];
    Object.keys(fields).forEach(function (key) {
      var value = fields[key];
      if (!value || !PREVIEW_FIELD_I18N[key]) return;
      list.push({ name: previewFieldLabel(key), value: value });
    });
    return list;
  }

  /** 一条预览的文本：「第 N 页 · 列名：取值 · …」（要素按列顺序，过长由 CSS 截断） */
  function buildPreviewText(p) {
    var parts = [$.i18n('files-import/batch-preview-page', p.page)];
    previewFieldList(p.fields).forEach(function (f) {
      if (f && f.value) {
        parts.push(f.name ? f.name + '：' + f.value : f.value);
      }
    });
    return parts.join(' · ');
  }

  /**
   * 渲染已展示的页。**增量插入**，不整块重建——重建会丢失滚动位置、内容跳动（像跑马灯）。
   * 新条目按页号插到正确位置（并发下后到的页页号可能更小），仍只对单条增删。
   * 一条为「第 N 页 · 各要素值」；容器固定可视高度约 6 行，超过即出竖向滚动条。
   */
  function renderPagePreview($banner) {
    if (previewShown.length === 0) return;
    var $box = $banner.find('.batch-extraction-banner-preview');
    if ($box.length === 0) {
      // 下行：标签行（右端为折叠箭头）+ 列表。折叠只切 class，不重建本块，
      // 因此进度轮询刷新时用户选定的折叠状态不会被重置
      $box = $('<div class="batch-extraction-banner-preview"></div>')
          .append($('<div class="batch-preview-header">')
              .append($('<span class="batch-preview-label">')
                  .text($.i18n('files-import/batch-preview-title')))
              .append($('<span class="batch-preview-latest">'))
              .append($('<button type="button" class="batch-preview-toggle">&#9662;</button>')
                  .on('click', function () {
                    $box.toggleClass('collapsed');
                  })))
          .append($('<div class="batch-preview-list"></div>'));
      $banner.append($box);
    }
    var $list = $box.find('.batch-preview-list');
    var keep = {};
    previewShown.forEach(function (p) {
      keep[p.page] = true;
    });
    // 丢弃已被上限挤出的条目（最旧的一端）
    $list.children('.batch-preview-item').each(function () {
      if (!keep[$(this).attr('data-page')]) {
        $(this).remove();
      }
    });
    var rendered = {};
    $list.children('.batch-preview-item').each(function () {
      rendered[$(this).attr('data-page')] = true;
    });
    var listEl = $list[0];
    // 用户本来就在底部时继续跟随最新，否则不动、尊重其滚动位置
    var follow = listEl.scrollHeight - listEl.scrollTop - listEl.clientHeight <= 20;
    previewShown.forEach(function (p) {
      if (rendered[p.page]) return;
      var $item = $('<span class="batch-preview-item">')
          .attr('data-page', p.page)
          .text(buildPreviewText(p));
      // 按页号插入到正确位置（局部 insertBefore，不重建整块，保住滚动位置）
      var $next = null;
      $list.children('.batch-preview-item').each(function () {
        if ($next) return;
        if (parseInt($(this).attr('data-page'), 10) > p.page) {
          $next = $(this);
        }
      });
      if ($next) {
        $item.insertBefore($next);
      } else {
        $list.append($item);
      }
    });
    if (follow) {
      listEl.scrollTop = listEl.scrollHeight;
    }
    // 收起时列表整体隐藏，把最新一条顶到标签后面，收起状态下也能看到进展
    $box.find('.batch-preview-latest')
        .text(buildPreviewText(previewShown[previewShown.length - 1]));
  }

  /**
   * 刷新数据表。
   *
   * keepPage 为真时保持当前所在页、并在用户本来位于底部时继续跟随新行。抽取期间表格是
   * 随件级行实时增长的，而 DataTableView.update() 默认会把 start 重置为 0——不保持页位置
   * 就会每次刷新都跳回第一页，新行却落在末页，看起来就像「一直没有新数据出来」。
   */
  function refreshDataTable(keepPage) {
    try {
      if (typeof FileViewPanel !== 'undefined' && typeof FileViewPanel.invalidatePageMap === 'function') {
        FileViewPanel.invalidatePageMap();
      }
    } catch (e) {
      // ignore
    }
    try {
      if (window.ui && ui.dataTableView && typeof ui.dataTableView.update === 'function') {
        ui.dataTableView.update(function () {
          try {
            // The core render fixes column widths from a cache; with an empty
            // growing table that cache pins narrow widths. Remove the inline
            // widths after render so columns re-fit their content.
            $('.data-table-container col').css('width', '');
          } catch (e) {
            // ignore
          }
          if (keepPage) {
            followTableBottom();
          }
        }, !!keepPage);
      }
    } catch (e) {
      // ignore
    }
  }

  function removeBanner() {
    if (bannerHideTimer) {
      window.clearTimeout(bannerHideTimer);
      bannerHideTimer = null;
    }
    if ($banner) {
      $banner.remove();
      $banner = null;
    }
  }

  function updateBanner(kind, d) {
    if (!$banner) {
      // 上行（100% 不透明）：状态图标 + 进度文案 + 进度条 + 关闭按钮。
      // 下行预览（半透明、可折叠）由 renderPagePreview 按需追加到 $banner
      var $head = $('<div class="batch-extraction-banner-head">')
          .append($('<span class="batch-extraction-banner-icon icon-running">'))
          .append($('<span class="batch-extraction-banner-text">'))
          .append(
              $('<div class="batch-progress-track batch-banner-progress-track">' +
                '<div class="batch-progress-bar batch-banner-progress-bar"></div></div>')
          )
          .append(
              // 右上角操作列：收缩按钮在上、关闭按钮在下（收缩按钮位于关闭按钮正上方）
              $('<div class="batch-extraction-banner-actions">')
                  .append(
                      $('<button type="button" class="batch-extraction-banner-toggle">&#9662;</button>')
                          .on('click', function () {
                            // 收缩：只保留标题行，图标/进度条/只读提示/页级预览全部隐藏；
                            // 再点一次恢复。只切 class，不重建本块，故轮询刷新不会重置收缩状态
                            $banner.toggleClass('collapsed');
                          })
                  )
                  .append(
                      $('<button type="button" class="batch-extraction-banner-close">&times;</button>')
                          .on('click', function () {
                            // 终态横幅：关闭后按项目持久化，刷新/重进不再出现；
                            // 运行中横幅：静默直到下一次进度更新
                            var pid = getProjectId();
                            var currentKind = $banner ? $banner.data('banner-kind') : null;
                            if (isFinalStatus(currentKind) && pid !== null) {
                              writeDismissedFinal(pid, currentKind);
                            } else if (currentKind === 'running') {
                              runningDismissed = {
                                processedPages: $banner.data('processed-pages') || 0,
                                rowsAppended: $banner.data('rows-appended') || 0
                              };
                            }
                            removeBanner();
                          })
                  )
          );
      $banner = $('<div class="batch-extraction-banner">').append($head);
      $('body').append($banner);
    }
    $banner.data('banner-kind', kind);
    if (kind === 'running') {
      $banner.data('processed-pages', d.processedPages || 0);
      $banner.data('rows-appended', d.rowsAppended || 0);
    }
    $banner.removeClass('banner-error');
    $banner.find('.batch-banner-progress-bar').removeClass('banner-bar-error');
    if (kind !== 'running') {
      // 终态：清掉预览与揭示队列，避免残留上一次运行的内容
      $banner.find('.batch-extraction-banner-preview').remove();
      resetPagePreview();
    }
    var $text = $banner.find('.batch-extraction-banner-text');
    var $bar = $banner.find('.batch-banner-progress-bar');
    var text = '';
    if (kind !== 'running') {
      // 终态：清除单调进度记忆，下一次提取从头计算
      $banner.removeData('last-percent');
    }
    if (kind === 'running') {
      // 耗时：批次开始时间由后端随 payload 回传，跨刷新稳定
      var startedAt = d.startedAt || 0;
      var elapsedMin = startedAt > 0
          ? Math.max(0, Math.round((Date.now() - startedAt) / 60000)) : 0;
      // 「总耗时预计」按页口径外推：法院案卷的实际成本与页数几乎成正比，而各卷页数
      // 相差很大（长卷 2-300 页、短卷几页），按件/卷数算完成度会让预估值跳变失真。
      // 故一律用 已处理页数 / 总页数；总页数缺失时才退回件/卷口径。
      var fraction = 0;
      if ((d.totalPages || 0) > 0) {
        fraction = (d.processedPages || 0) / d.totalPages;
      } else if ((d.totalFiles || 0) > 0) {
        fraction = ((d.processedFiles || 0) - 1
            + (typeof d.unitFraction === 'number' ? d.unitFraction : 0)) / d.totalFiles;
      }
      fraction = Math.max(0, Math.min(1, fraction));
      // 完成度过低时按比例外推会得出离谱的预估值，此时只显示已耗时
      var timingHint;
      if (startedAt > 0 && fraction >= 0.02) {
        var etaMin = Math.max(1, Math.round(elapsedMin / fraction));
        timingHint = $.i18n('files-import/batch-banner-elapsed', elapsedMin, etaMin);
      } else {
        timingHint = $.i18n('files-import/batch-banner-elapsed-only', elapsedMin);
      }
      // 「当前处理」在前、件内进度在后：当前处理：X，已完成 m / n 页。
      var unitHint = '';
      if (d.currentUnit) {
        unitHint = $.i18n('files-import/batch-banner-current', d.currentUnit);
        if (d.message) {
          unitHint += '，' + d.message;
        }
        unitHint += '。';
      }
      var unitLabel = $.i18n(d.unitKind === 'volume'
          ? 'files-import/batch-unit-volume' : 'files-import/batch-unit-case');
      text = $.i18n('files-import/batch-banner-running',
          d.processedFiles || 0, d.totalFiles || 0, unitLabel,
          d.processedPages || 0, d.totalPages || 0,
          d.rowsAppended || 0, timingHint, unitHint);
      // 进度条按件口径推进（已完成件数 + 当前件内完成度）。
      // 不能直接用 processedPages/totalPages：PDF 实际页数只能在处理中探明，
      // 分母被动态修正后移会让百分比回退，表现为进度条来回跳动。
      var percent;
      if ((d.totalFiles || 0) > 0) {
        percent = ((d.processedFiles || 0) - 1
            + (typeof d.unitFraction === 'number' ? d.unitFraction : 0)) * 100 / d.totalFiles;
      } else if ((d.totalPages || 0) > 0) {
        percent = (d.processedPages || 0) * 100 / d.totalPages;
      } else {
        percent = 0;
      }
      percent = Math.max(0, Math.min(100, Math.round(percent)));
      // 单调保护：同一任务内进度条只前进不后退
      var lastPercent = $banner.data('last-percent');
      if (typeof lastPercent === 'number' && percent < lastPercent) {
        percent = lastPercent;
      }
      $banner.data('last-percent', percent);
      $bar.css('width', percent + '%');
      if ($banner.find('.batch-extraction-banner-hint').length === 0) {
        $banner.find('.batch-extraction-banner-head')
            .append($('<span class="batch-extraction-banner-hint">')
                .text($.i18n('files-import/batch-readonly-hint')));
      }
      updatePreviewInterval(d.pageConcurrency, d.avgPageMillis);
      feedPagePreview($banner, d.recentPages, d.volumeIndex);
    } else if (kind === 'completed') {
      text = $.i18n('files-import/batch-banner-completed', d.rowsAppended || 0);
      $bar.css('width', '100%');
    } else if (kind === 'cancelled') {
      text = $.i18n('files-import/batch-banner-cancelled', d.rowsAppended || 0);
      $bar.css('width', '100%');
    } else {
      text = $.i18n('files-import/batch-banner-failed', d.message || '');
      $banner.addClass('banner-error');
      $bar.addClass('banner-bar-error');
      $bar.css('width', '100%');
    }
    // 终态已到：再按节奏揭示就来不及了——横幅很快被结果页（重建的项目 UI）替换掉
    if (kind !== 'running') {
      flushPagePreview($banner);
    }
    $text.text(text);
    // 状态图标：运行中转圈，终态切换为静态图标
    var iconClass = 'icon-running';
    if (kind === 'completed') {
      iconClass = 'icon-completed';
    } else if (kind === 'cancelled') {
      iconClass = 'icon-cancelled';
    } else if (kind !== 'running') {
      iconClass = 'icon-error';
    }
    $banner.find('.batch-extraction-banner-icon')
        .attr('class', 'batch-extraction-banner-icon ' + iconClass);
  }

  function showBanner(kind, d) {
    // 运行中横幅被用户关闭后，进度未变化前保持静默；
    // 一旦 processedPages/rowsAppended 有更新则重新出现
    if (kind === 'running' && runningDismissed &&
        (d.processedPages || 0) === runningDismissed.processedPages &&
        (d.rowsAppended || 0) === runningDismissed.rowsAppended) {
      return;
    }
    if (kind === 'running') {
      runningDismissed = null;
    }
    updateBanner(kind, d);
  }

  function showFinalBanner(kind, d) {
    // 用户已关闭过该终态横幅：不再出现（跨刷新持久化）
    var pid = getProjectId();
    if (pid !== null) {
      var dismissed = readDismissedFinal(pid);
      if (dismissed === kind) {
        return;
      }
    }
    updateBanner(kind, d);
    if (bannerHideTimer) window.clearTimeout(bannerHideTimer);
    bannerHideTimer = window.setTimeout(function () {
      removeBanner();
    }, FINAL_BANNER_MS);
  }

  function pollOnce() {
    var pid = getProjectId();
    if (pid === null) {
      stop();
      return;
    }
    Refine.wrapCSRF(function (token) {
      $.post("command/files/batch-extraction", {
        subCommand: "progress",
        project: pid,
        csrf_token: token
      }, function (data) {
        if (!data || data.code !== 'ok') {
          stop();
          return;
        }
        if (data.status === 'running') {
          // 新任务运行中：清除该项目旧的终态关闭记录，确保新任务的终态横幅可见
          clearDismissedFinal(pid);
          setReadonlyMode(true);
          showBanner('running', data);
          if (lastRowsAppended !== -1 && data.rowsAppended !== lastRowsAppended) {
            // 保持页位置并跟随最新行，否则每次刷新都跳回第一页，看不到新抽出的件
            refreshDataTable(true);
          }
          lastRowsAppended = data.rowsAppended;
        } else {
          stop();
          setReadonlyMode(false);
          // 重新拉取项目模型，让案卷级项目在抽取结束后出现「卷级」数据表标签页
          Refine.reinitializeProjectData(function () {
            refreshDataTable();
          });
          showFinalBanner(data.status, data);
        }
      }, "json").fail(function () {
        stop();
        setReadonlyMode(false);
      });
    });
  }

  function start() {
    if (pollTimer) return;
    pollOnce();
    pollTimer = window.setInterval(pollOnce, POLL_INTERVAL);
  }

  function stop() {
    if (pollTimer) {
      window.clearInterval(pollTimer);
      pollTimer = null;
    }
  }

  function setReadonlyMode(on) {
    try {
      $(document.body).toggleClass('extraction-readonly', !!on);
    } catch (e) {
      // ignore
    }
  }

  function installEditBlockers() {
    // R-07: during extraction the project is read-only. Block the most common
    // editing gestures up front (backend guard vetoes Change commands anyway).
    $(document).on('dblclick.extraction-readonly', '.data-table-cell', function (e) {
      if ($(document.body).hasClass('extraction-readonly')) {
        e.preventDefault();
        e.stopPropagation();
      }
    });
    $(document).on('click.extraction-readonly', '.data-table-star, .data-table-flag', function (e) {
      if ($(document.body).hasClass('extraction-readonly')) {
        e.preventDefault();
        e.stopPropagation();
      }
    });
  }

  $(function () {
    loadExtensionMessages();
    installEditBlockers();
    window.setTimeout(start, 1000);
  });

  return {};
})();


/* ===== /extension/data-quality/scripts/menu-bar-extension.js ===== */

/**
 * Data Quality Extension - Menu Bar Extension
 *
 * Registers the "Data Quality" menu in the ExtensionBar
 */

I18NUtil.init("data-quality");

// Extend the ExtensionBar with Data Quality menu
$(function() {
  ExtensionBar.MenuItems.push({
    "id": "data-quality",
    "label": $.i18n('data-quality-extension/menu-label'),
    "submenu": [
      {
        id: "data-quality/edit-rules",
        label: $.i18n('data-quality-extension/edit-rules'),
        click: function() {
          QualityAlignment.launch(false);
        }
      },
      {
        id: "data-quality/manage-rules",
        label: $.i18n('data-quality-extension/manage-rules'),
        click: function() {
          new ManageRulesDialog();
        }
      },
      {},  // separator
      {
        id: "data-quality/run-check",
        label: $.i18n('data-quality-extension/run-check'),
        click: function() {
          new RunCheckDialog();
        }
      }
    ]
  });

  // Auto-launch quality alignment tabs if rules or results exist
  // Use a small delay to ensure the UI is fully loaded
  console.log('[menu-bar-extension] Setting up auto-launch timeout...');
  setTimeout(function() {
    console.log('[menu-bar-extension] Timeout fired, QualityAlignment defined:', typeof QualityAlignment !== 'undefined');
    if (typeof QualityAlignment !== 'undefined') {
      // Check URL hash to activate specific tab
      var hash = window.location.hash;
      console.log('[menu-bar-extension] URL hash:', hash);

      // Always use autoLaunchIfNeeded to load saved rules/results first
      // Then switch to the requested tab based on hash
      if (hash === '#quality-rules' || hash === '#quality-results') {
        // Clear hash to prevent infinite loop on refresh
        history.replaceState(null, '', window.location.pathname + window.location.search);

        // Load saved data and launch with target tab
        QualityAlignment.autoLaunchIfNeededWithTarget(hash === '#quality-results' ? 'results' : 'rules');
      } else {
        // Normal auto-launch based on existing rules/results
        console.log('[menu-bar-extension] Calling autoLaunchIfNeeded...');
        QualityAlignment.autoLaunchIfNeeded();
      }
    } else {
      console.error('[menu-bar-extension] QualityAlignment is not defined!');
    }
  }, 500);
});



/* ===== /extension/data-quality/scripts/quality-alignment.js ===== */

/**
 * Data Quality Extension - Quality Alignment Module
 *
 * Main module for quality rules editing and results display.
 * Follows the pattern of wikibase's SchemaAlignment.
 */

var QualityAlignment = {
  _isSetUp: false,
  _hasUnsavedChanges: false,
  _currentRules: null,
  _currentResults: null,

  // Cell error map for cell marking: { "rowIndex_columnName": [error1, error2, ...] }
  _cellErrorMap: {},

  // Format check rules: { columnName: { nonEmpty: bool, unique: bool, regex: string, dateFormat: string, valueList: [] } }
  _formatRules: {},

  // Resource check config
  _resourceConfig: {
    basePath: '',
    pathFields: [],  // Array of column names used to build path
    pathMode: 'separator',  // 'separator' or 'template'
    separator: '',  // Will use system default if empty
    template: '',   // Template string like {0}/{1}/{2}
    folderChecks: {
      existence: true,
      dataExistence: true,
      nameFormat: '',
      sequential: true
    },
    fileChecks: {
      countMatch: true,
      countColumn: '',
      nameFormat: '',
      sequential: true
    }
  },

  // Content comparison rules: [{ column: '', extractLabel: '', threshold: 100 }]
  _contentRules: [],

  // AIMP service configuration - supports both 7998 and 7999 interface modes
  _aimpConfig: {
    serviceUrl: '',
    interfaceMode: 'auto'  // '7998', '7999', or 'auto'
  }
};

/**
 * Get the appropriate API endpoint for a check type based on interface mode
 * @param {string} serviceUrl - Base service URL
 * @param {string} interfaceMode - '7998' or '7999'
 * @param {string} checkType - Type of check (blank, stain, edge, hole, bias, dpi, bitdepth)
 * @returns {string} - Full API endpoint URL
 */
QualityAlignment._getApiEndpoint = function(serviceUrl, interfaceMode, checkType) {
  // Normalize base URL
  var baseUrl = serviceUrl.replace(/\/$/, '');
  
  if (interfaceMode === '7999') {
    // 7999 mode uses individual endpoints
    var endpoints = {
      'blank': '/blank',
      'stain': '/stain',
      'edge': '/edge',
      'hole': '/house',
      'bias': '/rectify',
      'dpi': '/dpi',
      'bitdepth': '/bitdepth',
      'quality': '/jpeg/quality'
    };
    return baseUrl + (endpoints[checkType] || '/' + checkType);
  } else {
    // 7998 mode uses unified extract endpoint
    return baseUrl + '/api/ocr/extract';
  }
};

/**
 * Launch the quality alignment panel
 * @param {boolean} showResults - If true, show results tab; otherwise show rules tab
 */
QualityAlignment.launch = function(showResults, saveState) {
  console.log('[QualityAlignment.launch] 被调用, showResults:', showResults);
  if (!this._isSetUp) {
    console.log('[QualityAlignment.launch] _isSetUp为false，调用setUpTabs');
    this.setUpTabs();
  }

  if (showResults) {
    console.log('[QualityAlignment.launch] 调用_renderResultsTab');
    // Always re-render results tab when showing results to ensure latest data is displayed
    this._renderResultsTab();
    console.log('[QualityAlignment.launch] 调用switchTab切换到results');
    this.switchTab('#quality-results-panel', saveState);
  } else {
    console.log('[QualityAlignment.launch] 调用switchTab切换到rules');
    this.switchTab('#quality-rules-panel', saveState);
  }
};

/**
 * Check if any quality rules are configured
 */
QualityAlignment._hasAnyRules = function() {
  // Check format rules
  if (this._formatRules && Object.keys(this._formatRules).length > 0) {
    return true;
  }
  // Check content rules
  if (this._contentRules && this._contentRules.length > 0) {
    return true;
  }
  // Check resource config - if basePath is set
  if (this._resourceConfig && this._resourceConfig.basePath) {
    return true;
  }
  return false;
};

/**
 * Check if there are any quality check results
 */
QualityAlignment._hasResults = function() {
  if (!this._currentResults) {
    return false;
  }
  // Has errors OR service unavailable (needs to show alert)
  if (this._currentResults.errors && this._currentResults.errors.length > 0) {
    return true;
  }
  // Also consider service unavailable as having "results" to display
  if (this._currentResults.serviceUnavailable) {
    return true;
  }
  return false;
};

/**
 * Build cell error map from current results for cell marking
 * Map structure: { "rowIndex_columnName": [error1, error2, ...] }
 */
QualityAlignment._buildCellErrorMap = function() {
  this._cellErrorMap = {};

  if (!this._currentResults || !this._currentResults.errors) {
    return;
  }

  var errors = this._currentResults.errors;
  for (var i = 0; i < errors.length; i++) {
    var error = errors[i];
    // Only map errors that have both rowIndex and column
    if (error.rowIndex !== undefined && error.rowIndex !== null && error.column) {
      var key = error.rowIndex + '_' + error.column;
      if (!this._cellErrorMap[key]) {
        this._cellErrorMap[key] = [];
      }
      this._cellErrorMap[key].push(error);
    }
  }

  console.log('[QualityAlignment] Cell error map built with', Object.keys(this._cellErrorMap).length, 'cells');
};

/**
 * Refresh data table to show error markers
 */
QualityAlignment._refreshDataTable = function() {
  if (typeof ui !== 'undefined' && ui.dataTableView) {
    ui.dataTableView.render();
  }
};

/**
 * Auto-launch tabs if rules or results exist
 * Called on page load
 */
QualityAlignment.autoLaunchIfNeeded = function() {
  var self = this;
  console.log('[QualityAlignment] autoLaunchIfNeeded called for project:', theProject.id);

  // Load rules and results in parallel
  var rulesLoaded = false;
  var resultsLoaded = false;
  var hasRules = false;
  var hasResults = false;

  function checkAndLaunch() {
    if (!rulesLoaded || !resultsLoaded) return;

    // Only launch if there are actual rules configured
    // Don't auto-launch just because there are saved results
    if (hasRules) {
      // Check if this is a page refresh (has saved tab state) or new project entry
      var savedTab = sessionStorage.getItem('quality_current_tab_' + theProject.id);
      var isRefresh = savedTab !== null;

      // Initialize tabs without saving state (saveState = false)
      self.launch(hasResults, false);

      if (isRefresh) {
        // Page refresh: restore to saved tab
        if (savedTab === '#view-panel') {
          self.switchTab('#view-panel', false);
        } else if (savedTab === '#quality-results-panel' && hasResults) {
          self.switchTab('#quality-results-panel', false);
        } else if (savedTab === '#quality-rules-panel') {
          self.switchTab('#quality-rules-panel', false);
        }
      } else {
        // New project entry: switch to data view after tabs are initialized
        self.switchTab('#view-panel', false);
      }
    } else if (hasResults) {
      // Only have results but no rules - this shouldn't happen in normal flow
      // Just load results without launching tabs
      console.log('[QualityAlignment] Found results but no rules, loading results only');
      self._currentResults = self._lastCheckResult;
      self._buildCellErrorMap();
      self._refreshDataTable();
    } else {
      console.log('[QualityAlignment] No rules or results found, skipping auto-launch');
    }
  }

  // Load rules
  $.ajax({
    url: "command/data-quality/get-quality-rules",
    type: "GET",
    data: { project: theProject.id },
    dataType: "json",
    success: function(response) {
      if (response.code === "ok" && response.rules) {
        self._formatRules = response.rules.formatRules || {};
        self._resourceConfig = response.rules.resourceConfig || self._getDefaultResourceConfig();
        self._contentRules = response.rules.contentRules || [];
        self._aimpConfig = response.rules.aimpConfig || { serviceUrl: '' };

        hasRules = self._hasAnyRules();

        // If AIMP service URL is configured, test connection
        if (self._aimpConfig.serviceUrl) {
          self._testAndUpdateAimpConnection(self._aimpConfig.serviceUrl);
        }
      }
      rulesLoaded = true;
      checkAndLaunch();
    },
    error: function() {
      rulesLoaded = true;
      checkAndLaunch();
    }
  });

  // Load previous results
  console.log('[QualityAlignment] Loading previous results...');
  $.ajax({
    url: "command/data-quality/get-quality-result",
    type: "GET",
    data: { project: theProject.id },
    dataType: "json",
    success: function(response) {
      console.log('[QualityAlignment] get-quality-result response:', response);
      if (response.code === "ok" && response.hasResult && response.result) {
        self._currentResults = response.result;
        self._lastCheckResult = response.result;
        hasResults = true;
        console.log('[QualityAlignment] Found saved results with', response.result.errors ? response.result.errors.length : 0, 'errors');
        if (response.result.errors && response.result.errors.length > 0) {
          console.log('[QualityAlignment] Sample error structure:', response.result.errors[0]);
          console.log('[QualityAlignment] Error categories:', response.result.errors.map(function(e) { return e.category; }).filter(function(c, i, a) { return a.indexOf(c) === i; }));
          // 详细检查前5个错误的 hiddenFileName
          for (var i = 0; i < Math.min(5, response.result.errors.length); i++) {
            var error = response.result.errors[i];
            console.log('[QualityAlignment] Error ' + i + ':', {
              rowIndex: error.rowIndex,
              column: error.column,
              value: error.value,
              errorType: error.errorType,
              message: error.message,
              hiddenFileName: error.hiddenFileName,
              locationX: error.locationX,
              locationY: error.locationY
            });
          }
        }
        // Build cell error map for cell marking
        self._buildCellErrorMap();
        self._refreshDataTable();
      } else {
        console.log('[QualityAlignment] No saved results found');
      }
      resultsLoaded = true;
      checkAndLaunch();
    },
    error: function(xhr, status, error) {
      console.error('[QualityAlignment] Error loading results:', status, error);
      resultsLoaded = true;
      checkAndLaunch();
    }
  });
};

/**
 * Auto-launch with a specific target tab (called when URL has hash)
 * @param {string} target - 'rules' or 'results'
 */
QualityAlignment.autoLaunchIfNeededWithTarget = function(target) {
  var self = this;
  console.log('[QualityAlignment] autoLaunchIfNeededWithTarget called, target:', target);

  // Load rules and results in parallel
  var rulesLoaded = false;
  var resultsLoaded = false;

  function launchWithTarget() {
    if (!rulesLoaded || !resultsLoaded) return;

    console.log('[QualityAlignment] Both loaded, launching with target:', target);
    // Always launch tabs
    var showResults = (target === 'results');
    self.launch(showResults, true);

    // Switch to target tab after launch
    if (target === 'results') {
      self.switchTab('#quality-results-panel', false);
    } else {
      self.switchTab('#quality-rules-panel', false);
    }
  }

  // Load rules
  $.ajax({
    url: "command/data-quality/get-quality-rules",
    type: "GET",
    data: { project: theProject.id },
    dataType: "json",
    success: function(response) {
      if (response.code === "ok" && response.rules) {
        self._formatRules = response.rules.formatRules || {};
        self._resourceConfig = response.rules.resourceConfig || self._getDefaultResourceConfig();
        self._contentRules = response.rules.contentRules || [];
        self._aimpConfig = response.rules.aimpConfig || { serviceUrl: '' };
      }
      rulesLoaded = true;
      launchWithTarget();
    },
    error: function() {
      rulesLoaded = true;
      launchWithTarget();
    }
  });

  // Load previous results
  $.ajax({
    url: "command/data-quality/get-quality-result",
    type: "GET",
    data: { project: theProject.id },
    dataType: "json",
    success: function(response) {
      console.log('[QualityAlignment] get-quality-result response:', response);
      if (response.code === "ok" && response.hasResult && response.result) {
        self._currentResults = response.result;
        self._lastCheckResult = response.result;
        console.log('[QualityAlignment] Found saved results with', response.result.errors ? response.result.errors.length : 0, 'errors');
        self._buildCellErrorMap();
        self._refreshDataTable();
      }
      resultsLoaded = true;
      launchWithTarget();
    },
    error: function() {
      resultsLoaded = true;
      launchWithTarget();
    }
  });
};

/**
 * Check if tabs are set up
 */
QualityAlignment.isSetUp = function() {
  return this._isSetUp;
};

/**
 * Set up the tabs in the UI
 */
QualityAlignment.setUpTabs = function() {
  this._isSetUp = true;
  this._rightPanel = $('#right-panel');
  this._viewPanel = $('#view-panel').addClass('main-view-panel-tab');
  this._toolPanel = $('#tool-panel');

  // Get sheet name for display
  var sheetName = '数据';
  var isMultiSheet = false;

  if (theProject.sheetDataMap) {
    var sheetIds = Object.keys(theProject.sheetDataMap);
    isMultiSheet = sheetIds.length > 1;
    if (sheetIds.length === 1) {
      var sheetData = theProject.sheetDataMap[sheetIds[0]];
      if (sheetData && sheetData.sheetName) {
        sheetName = sheetData.sheetName;
      }
    }
  }

  // For single sheet, create a data tab with sheet name
  if (!isMultiSheet) {
    // Create a data tab for single sheet
    this._dataTab = $('<div></div>')
      .addClass('main-view-panel-tab-header')
      .addClass('quality-data-tab')
      .attr('href', '#view-panel')
      .text(sheetName)
      .insertBefore('#summary-bar');

    // Keep summary bar visible and make it clickable
    this._summaryBar = $('#summary-bar')
      .addClass('main-view-panel-tab-header')
      .attr('href', '#view-panel')
      .css('cursor', 'pointer')
      .css('pointer-events', 'auto');

    // Register the data tab
    TabManager.registerTabGroup('quality-tabs', '#tool-panel');
    TabManager.registerTab('quality-tabs', this._dataTab, '#view-panel', function(e) {
      // View panel tab click handler
    }, 0);
  } else {
    // Multi-sheet project, use original behavior
    this._summaryBar = $('#summary-bar')
      .addClass('main-view-panel-tab-header')
      .addClass('active')
      .css('cursor', 'default')
      .css('pointer-events', 'none')
      .removeAttr('href');

    TabManager.registerTabGroup('quality-tabs', '#tool-panel');
  }

  // Create Quality Rules Panel
  this._rulesPanel = $('<div id="quality-rules-panel"></div>')
    .addClass('main-view-panel-tab')
    .appendTo(this._rightPanel);

  // Create Check Results Panel
  this._resultsPanel = $('<div id="quality-results-panel"></div>')
    .addClass('main-view-panel-tab')
    .appendTo(this._rightPanel);

  // Add tab headers to tool panel
  var rulesButton = $('<div></div>')
    .addClass('main-view-panel-tab-header')
    .attr('href', '#quality-rules-panel')
    .text($.i18n('data-quality-extension/rules-tab-header'))
    .appendTo(this._toolPanel);

  this._unsavedIndicator = $('<span></span>')
    .html('&nbsp;*')
    .attr('title', 'Unsaved changes')
    .hide()
    .appendTo(rulesButton);

  var resultsButton = $('<div></div>')
    .addClass('main-view-panel-tab-header')
    .attr('href', '#quality-results-panel')
    .text($.i18n('data-quality-extension/results-tab-header'))
    .appendTo(this._toolPanel);

  this._resultsCount = $('<span></span>')
    .addClass('quality-results-count')
    .appendTo(resultsButton)
    .hide();

  // Register quality tabs with TabManager
  // For single sheet, use the data tab instead of summary bar
  var viewTab = this._dataTab || this._summaryBar;
  TabManager.registerTab('quality-tabs', viewTab, '#view-panel', function(e) {
    // View panel tab click handler
  }, 0);
  
  TabManager.registerTab('quality-tabs', rulesButton, '#quality-rules-panel', function(e) {
    // Rules tab click handler
  }, 100);
  
  TabManager.registerTab('quality-tabs', resultsButton, '#quality-results-panel', function(e) {
    // Results tab click handler
  }, 200);

  // Load existing rules from project
  this._loadRules();

  // Initialize tab content
  this._renderRulesTab();
  this._renderResultsTab();
};

/**
 * Switch to a specific tab
 * @param {string} targetTab - The target tab selector
 * @param {boolean} saveState - Whether to save tab state (default: true)
 */
QualityAlignment.switchTab = function(targetTab, saveState) {
  var targetTabElement = $('.main-view-panel-tab-header[href="' + targetTab + '"]');
  TabManager.switchTab('quality-tabs', targetTabElement);

  // Save current tab state for page refresh (unless explicitly disabled)
  if (saveState !== false) {
    try {
      sessionStorage.setItem('quality_current_tab_' + theProject.id, targetTab);
    } catch (e) {
      // Ignore storage errors
    }
  }
};

/**
 * Render the rules tab content
 */
QualityAlignment._renderRulesTab = function() {
  var self = this;
  this._rulesPanel.empty();
  
  var container = $('<div class="quality-rules-container"></div>')
    .appendTo(this._rulesPanel);
  
  // Sub-tabs for different rule types
  var subTabsHeader = $('<div class="quality-sub-tabs-header"></div>')
    .appendTo(container);
  
  var subTabsContent = $('<div class="quality-sub-tabs-content"></div>')
    .appendTo(container);
  
  // Create sub-tabs
  var subTabs = [
    { id: 'format-check', label: $.i18n('data-quality-extension/format-check-tab') },
    { id: 'resource-check', label: $.i18n('data-quality-extension/resource-check-tab') },
    { id: 'content-check', label: $.i18n('data-quality-extension/content-check-tab') },
    { id: 'image-quality', label: $.i18n('data-quality-extension/image-quality-tab') }
  ];
  
  subTabs.forEach(function(tab, index) {
    var tabHeader = $('<div class="quality-sub-tab-header"></div>')
      .attr('data-tab', tab.id)
      .text(tab.label)
      .appendTo(subTabsHeader);
    
    if (index === 0) {
      tabHeader.addClass('active');
    }
    
    var tabContent = $('<div class="quality-sub-tab-content"></div>')
      .attr('id', 'quality-' + tab.id + '-content')
      .appendTo(subTabsContent);
    
    if (index !== 0) {
      tabContent.hide();
    }
    
    tabHeader.on('click', function() {
      self._switchSubTab(tab.id);
    });
  });
  
  // Render each sub-tab content
  this._renderFormatCheckTab();
  this._renderResourceCheckTab();
  this._renderContentCheckTab();
  this._renderImageQualityTab();

  // Restore saved sub-tab state
  try {
    var savedSubTab = sessionStorage.getItem('quality_current_subtab_' + theProject.id);
    if (savedSubTab && subTabs.some(function(tab) { return tab.id === savedSubTab; })) {
      this._switchSubTab(savedSubTab, false);
    }
  } catch (e) {
    // Ignore storage errors
  }

  // Save button
  var buttonBar = $('<div class="quality-button-bar"></div>')
    .appendTo(container);

  $('<button class="button"></button>')
    .text($.i18n('data-quality-extension/save-rules'))
    .on('click', function() {
      self._saveRules();
    })
    .appendTo(buttonBar);
};

/**
 * Switch sub-tab
 * @param {string} tabId - The tab ID to switch to
 * @param {boolean} saveState - Whether to save tab state (default: true)
 */
QualityAlignment._switchSubTab = function(tabId, saveState) {
  $('.quality-sub-tab-header').removeClass('active');
  $('.quality-sub-tab-header[data-tab="' + tabId + '"]').addClass('active');

  $('.quality-sub-tab-content').hide();
  $('#quality-' + tabId + '-content').show();

  if (tabId === 'image-quality' && typeof ImageQualityTab !== 'undefined') {
    ImageQualityTab._initResourceConfig();
  }

  // Save current sub-tab state for page refresh (unless explicitly disabled)
  if (saveState !== false) {
    try {
      sessionStorage.setItem('quality_current_subtab_' + theProject.id, tabId);
    } catch (e) {
      // Ignore storage errors
    }
  }
};

/**
 * Render format check sub-tab
 */
QualityAlignment._renderFormatCheckTab = function() {
  var self = this;
  var container = $('#quality-format-check-content');
  container.empty();

  // Template selector
  var templateRow = $('<div class="quality-template-row"></div>')
    .appendTo(container);

  $('<label></label>')
    .text($.i18n('data-quality-extension/rule-template-label'))
    .appendTo(templateRow);

  this._formatTemplateSelect = $('<select class="quality-template-select"></select>')
    .appendTo(templateRow);

  $('<option value=""></option>')
    .text('-- ' + $.i18n('data-quality-extension/select-template') + ' --')
    .appendTo(this._formatTemplateSelect);

  $('<option value="document-2022"></option>')
    .text($.i18n('data-quality-extension/template-document-2022'))
    .appendTo(this._formatTemplateSelect);

  $('<option value="document-1999" disabled></option>')
    .text($.i18n('data-quality-extension/template-document-1999') + ' (' + $.i18n('data-quality-extension/not-implemented') + ')')
    .appendTo(this._formatTemplateSelect);

  $('<option value="document-1985" disabled></option>')
    .text($.i18n('data-quality-extension/template-document-1985') + ' (' + $.i18n('data-quality-extension/not-implemented') + ')')
    .appendTo(this._formatTemplateSelect);

  $('<button class="button"></button>')
    .text($.i18n('data-quality-extension/apply-template'))
    .on('click', function() {
      self._applyFormatTemplate(self._formatTemplateSelect.val());
    })
    .appendTo(templateRow);

  // Section title
  $('<p class="quality-section-title"></p>')
    .text($.i18n('data-quality-extension/column-rules-list'))
    .appendTo(container);

  // Rules table
  var rulesTable = $('<table class="quality-rules-table"></table>')
    .appendTo(container);

  var thead = $('<thead></thead>').appendTo(rulesTable);
  var headerRow = $('<tr></tr>').appendTo(thead);
  $('<th></th>').text($.i18n('data-quality-extension/column-name')).appendTo(headerRow);
  $('<th></th>').text($.i18n('data-quality-extension/check-items')).appendTo(headerRow);
  $('<th></th>').text($.i18n('data-quality-extension/actions')).appendTo(headerRow);

  this._formatRulesBody = $('<tbody id="format-rules-body"></tbody>').appendTo(rulesTable);

  // Render existing rules
  this._refreshFormatRulesTable();

  // Add rule button
  var addRuleRow = $('<div class="quality-add-rule-row"></div>')
    .appendTo(container);

  $('<button class="button"></button>')
    .text('+ ' + $.i18n('data-quality-extension/add-column-rule'))
    .on('click', function() {
      self._addFormatRule();
    })
    .appendTo(addRuleRow);
};

/**
 * Refresh the format rules table
 */
QualityAlignment._refreshFormatRulesTable = function() {
  var self = this;
  this._formatRulesBody.empty();

  var ruleKeys = Object.keys(this._formatRules);
  if (ruleKeys.length === 0) {
    var emptyRow = $('<tr></tr>').appendTo(this._formatRulesBody);
    $('<td colspan="3" class="quality-placeholder"></td>')
      .text($.i18n('data-quality-extension/no-rules-configured'))
      .appendTo(emptyRow);
    return;
  }

  // Get all project column names for matching check
  var projectColumnNames = [];
  var columnNameToSheetMap = {};
  
  var isMultiSheet = theProject.sheetDataMap && Object.keys(theProject.sheetDataMap).length > 1;
  
  if (isMultiSheet) {
    var sheets = theProject.sheetDataMap;
    for (var sheetId in sheets) {
      if (sheets.hasOwnProperty(sheetId)) {
        var sheetData = sheets[sheetId];
        if (sheetData.columnModel && sheetData.columnModel.columns) {
          sheetData.columnModel.columns.forEach(function(col) {
            if (projectColumnNames.indexOf(col.name) === -1) {
              projectColumnNames.push(col.name);
            }
            // Store all sheet IDs for this column name
            if (!columnNameToSheetMap[col.name]) {
              columnNameToSheetMap[col.name] = [];
            }
            if (columnNameToSheetMap[col.name].indexOf(sheetId) === -1) {
              columnNameToSheetMap[col.name].push(sheetId);
            }
          });
        }
      }
    }
  } else {
    projectColumnNames = theProject.columnModel.columns.map(function(col) { return col.name; });
  }

  ruleKeys.forEach(function(key) {
    var rule = self._formatRules[key];
    var row = $('<tr></tr>').appendTo(self._formatRulesBody);

    // Parse key to get column name and sheet ID
    var columnName = key;
    var sheetId = '';
    if (key.indexOf('|') !== -1) {
      var parts = key.split('|');
      columnName = parts[0];
      sheetId = parts[1];
    }

    // Column name - add * if not matched
    var displayName = columnName;
    var isMatched = rule._matched !== false;
    var sheetNames = [];
    
    // Get sheet name from rule if available
    if (sheetId && theProject.sheetDataMap && theProject.sheetDataMap[sheetId]) {
      sheetNames.push(theProject.sheetDataMap[sheetId].sheetName);
    } else if (rule._sheetIds && Array.isArray(rule._sheetIds) && rule._sheetIds.length > 0) {
      // Fallback to _sheetIds if available
      rule._sheetIds.forEach(function(sid) {
        if (theProject.sheetDataMap && theProject.sheetDataMap[sid]) {
          sheetNames.push(theProject.sheetDataMap[sid].sheetName);
        }
      });
    } else if (columnNameToSheetMap[columnName]) {
      // Fallback to columnNameToSheetMap
      var sheetIds = columnNameToSheetMap[columnName];
      if (Array.isArray(sheetIds)) {
        sheetIds.forEach(function(sid) {
          if (theProject.sheetDataMap && theProject.sheetDataMap[sid]) {
            sheetNames.push(theProject.sheetDataMap[sid].sheetName);
          }
        });
      }
    }
    
    if (!isMatched) {
      displayName = columnName + ' *';
      row.addClass('unmatched-column');
    }
    var nameCell = $('<td></td>').appendTo(row);
    $('<span></span>').text(displayName).appendTo(nameCell);
    
    // Add sheet names if available
    if (sheetNames.length > 0) {
      var badgeText = '[' + sheetNames.join(', ') + ']';
      $('<span class="sheet-name-badge"></span>')
        .text(badgeText)
        .appendTo(nameCell);
    }
    
    if (!isMatched) {
      $('<span class="unmatched-hint"></span>')
        .text(' (' + $.i18n('data-quality-extension/unmatched') + ')')
        .appendTo(nameCell);
    }

    // Check items
    var checkItemsCell = $('<td></td>').appendTo(row);
    var checkItemsContainer = $('<span></span>').appendTo(checkItemsCell);

    var checkParts = [];
    if (rule.nonEmpty) checkParts.push($.i18n('data-quality-extension/check-non-empty'));
    if (rule.unique) checkParts.push($.i18n('data-quality-extension/check-unique'));
    if (rule.regex) checkParts.push($.i18n('data-quality-extension/check-regex') + ': ' + rule.regex);
    if (rule.dateFormat) checkParts.push($.i18n('data-quality-extension/check-date-format') + ': ' + rule.dateFormat);
    if (rule.typoCheckEnabled) checkParts.push($.i18n('data-quality-extension/check-typo'));

    if (checkParts.length > 0) {
      checkItemsContainer.text(checkParts.join(', '));
    }

    // Value list - make it clickable to show content
    if (rule.valueList && rule.valueList.length > 0) {
      if (checkParts.length > 0) {
        $('<span></span>').text(', ').appendTo(checkItemsCell);
      }
      var valueListLink = $('<a href="javascript:void(0)" class="value-list-link"></a>')
        .text($.i18n('data-quality-extension/check-value-list') + ' (' + rule.valueList.length + ')')
        .attr('title', $.i18n('data-quality-extension/click-to-view'))
        .on('click', function(e) {
          e.stopPropagation();
          self._showValueListPopup(key, rule.valueList, $(this));
        })
        .appendTo(checkItemsCell);
    }

    if (checkParts.length === 0 && (!rule.valueList || rule.valueList.length === 0)) {
      checkItemsCell.text('-');
    }

    // Actions
    var actionsCell = $('<td></td>').appendTo(row);
    $('<button class="button small-button"></button>')
      .text($.i18n('data-quality-extension/edit'))
      .on('click', function() {
        self._editFormatRule(key);
      })
      .appendTo(actionsCell);
    $('<button class="button small-button danger-button"></button>')
      .text($.i18n('data-quality-extension/delete'))
      .on('click', function() {
        self._deleteFormatRule(key);
      })
      .appendTo(actionsCell);
  });
};

/**
 * Show value list popup
 */
QualityAlignment._showValueListPopup = function(key, valueList, anchorElement) {
  var columnName = key;
  if (key.indexOf('|') !== -1) {
    var parts = key.split('|');
    columnName = parts[0];
  }

  // Remove any existing popup
  $('.value-list-popup').remove();

  var popup = $('<div class="value-list-popup"></div>');
  var header = $('<div class="value-list-popup-header"></div>').appendTo(popup);
  $('<span></span>').text($.i18n('data-quality-extension/value-list-for') + ' ' + columnName).appendTo(header);
  $('<button class="value-list-popup-close">&times;</button>')
    .on('click', function() { popup.remove(); })
    .appendTo(header);

  var content = $('<div class="value-list-popup-content"></div>').appendTo(popup);
  var list = $('<ul class="value-list-items"></ul>').appendTo(content);

  valueList.forEach(function(value) {
    $('<li></li>').text(value).appendTo(list);
  });

  // Position popup near anchor element
  popup.appendTo('body');
  var offset = anchorElement.offset();
  popup.css({
    left: offset.left,
    top: offset.top + anchorElement.outerHeight() + 5
  });

  // Close on click outside
  $(document).one('click', function(e) {
    if (!$(e.target).closest('.value-list-popup, .value-list-link').length) {
      popup.remove();
    }
  });
};

/**
 * Render resource check sub-tab
 */
QualityAlignment._renderResourceCheckTab = function() {
  var self = this;
  var container = $('#quality-resource-check-content');
  container.empty();

  var columns = theProject.columnModel.columns;

  // Resource location section
  $('<p class="quality-section-title"></p>')
    .text($.i18n('data-quality-extension/resource-location'))
    .appendTo(container);

  var locationSection = $('<div class="quality-config-section quality-path-config-section"></div>')
    .appendTo(container);

  // Configure path button and preview
  var pathConfigRow = $('<div class="quality-path-config-row"></div>').appendTo(locationSection);

  $('<button class="button"></button>')
    .text($.i18n('data-quality-extension/configure-path'))
    .on('click', function() {
      self._showPathConfigDialog();
    })
    .appendTo(pathConfigRow);

  // Path preview display
  this._pathPreviewSpan = $('<span class="quality-path-preview"></span>').appendTo(pathConfigRow);
  this._updatePathPreview();

  // Folder level checks
  $('<p class="quality-section-title"></p>')
    .text($.i18n('data-quality-extension/folder-level-checks'))
    .appendTo(container);

  var folderSection = $('<div class="quality-config-section"></div>').appendTo(container);

  var folderExistenceRow = this._renderCheckbox(folderSection, 'folder-existence', $.i18n('data-quality-extension/folder-existence'),
    this._resourceConfig.folderChecks.existence, function(v) { self._resourceConfig.folderChecks.existence = v; });
  $('<span></span>').text($.i18n('data-quality-extension/folder-existence-comment')).appendTo(folderExistenceRow);

  var dataExistenceRow = this._renderCheckbox(folderSection, 'data-existence', $.i18n('data-quality-extension/data-existence'),
    this._resourceConfig.folderChecks.dataExistence, function(v) { self._resourceConfig.folderChecks.dataExistence = v; });
  $('<span></span>').text($.i18n('data-quality-extension/data-existence-comment')).appendTo(dataExistenceRow);

  var nameFormatRow = this._renderCheckboxWithInput(folderSection, 'folder-name-format',
    $.i18n('data-quality-extension/folder-name-format'), !!this._resourceConfig.folderChecks.nameFormat,
    this._resourceConfig.folderChecks.nameFormat,
    function(checked) { if (!checked) self._resourceConfig.folderChecks.nameFormat = ''; },
    function(val) { self._resourceConfig.folderChecks.nameFormat = val; }, true);

  this._renderCheckbox(folderSection, 'folder-sequential', $.i18n('data-quality-extension/folder-sequential'),
    this._resourceConfig.folderChecks.sequential, function(v) { self._resourceConfig.folderChecks.sequential = v; });

  var emptyFolderRow = this._renderCheckbox(folderSection, 'folder-empty-folder', $.i18n('data-quality-extension/empty-folders-check'),
    this._resourceConfig.folderChecks.emptyFolder, function(v) { self._resourceConfig.folderChecks.emptyFolder = v; });
  $('<span></span>').text($.i18n('data-quality-extension/empty-folders-check-comment')).appendTo(emptyFolderRow);

  // File level checks
  $('<p class="quality-section-title"></p>')
    .text($.i18n('data-quality-extension/file-level-checks'))
    .appendTo(container);

  var fileSection = $('<div class="quality-config-section"></div>').appendTo(container);

  var countRow = $('<div class="quality-checkbox-row"></div>').appendTo(fileSection);
  $('<label></label>')
    .html('<input type="checkbox" id="check-file-count" ' + (this._resourceConfig.fileChecks.countMatch ? 'checked' : '') + '> '
      + $.i18n('data-quality-extension/file-count-match'))
    .appendTo(countRow);
  var span = $('<span></span>').text($.i18n('data-quality-extension/count-column')).appendTo(countRow);
  this._countColumnSelect = $('<select class="quality-text-input"></select>').appendTo(span);
  $('<option value=""></option>').text('-- ' + $.i18n('data-quality-extension/select-column') + ' --').appendTo(this._countColumnSelect);
  columns.forEach(function(col) {
    $('<option></option>').val(col.name).text(col.name).appendTo(self._countColumnSelect);
  });
  this._countColumnSelect.val(this._resourceConfig.fileChecks.countColumn);
  this._countColumnSelect.on('change', function() { self._resourceConfig.fileChecks.countColumn = $(this).val(); });

  countRow.find('#check-file-count').on('change', function() {
    self._resourceConfig.fileChecks.countMatch = $(this).prop('checked');
  });

  this._renderCheckboxWithInput(fileSection, 'file-name-format',
    $.i18n('data-quality-extension/file-name-format'), !!this._resourceConfig.fileChecks.nameFormat,
    this._resourceConfig.fileChecks.nameFormat,
    function(checked) { if (!checked) self._resourceConfig.fileChecks.nameFormat = ''; },
    function(val) { self._resourceConfig.fileChecks.nameFormat = val; }, true);

  this._renderCheckbox(fileSection, 'file-sequential', $.i18n('data-quality-extension/file-sequential'),
    this._resourceConfig.fileChecks.sequential, function(v) { self._resourceConfig.fileChecks.sequential = v; });
};

/**
 * Render image quality sub-tab
 */
QualityAlignment._renderImageQualityTab = function() {
  var self = this;
  var container = $('#quality-image-quality-content');
  container.empty();

  // Load image quality tab HTML
  var frame = $(DOM.loadHTML('data-quality', 'scripts/dialogs/image-quality-tab.html'));
  container.html(frame);

  // Process data-i18n attributes for translation
  container.find('[data-i18n]').each(function() {
    var key = $(this).attr('data-i18n');
    var text = $.i18n(key);
    if (text) {
      $(this).text(text);
    }
  });

  // Initialize the ImageQualityTab module
  if (typeof ImageQualityTab !== 'undefined') {
    ImageQualityTab.setUpUI();
  } else {
    console.error('[QualityAlignment] ImageQualityTab module not loaded');
    $('<p class="error-message"></p>')
      .text('ImageQualityTab模块未加载')
      .appendTo(container);
  }
};

/**
 * Helper: render a checkbox
 */
QualityAlignment._renderCheckbox = function(container, id, label, checked, onChange) {
  var row = $('<div class="quality-checkbox-row"></div>').appendTo(container);
  var checkbox = $('<input type="checkbox" id="check-' + id + '">')
    .prop('checked', checked)
    .on('change', function() { onChange($(this).prop('checked')); });
  $('<label></label>').append(checkbox).append(' ' + label).appendTo(row);
  return row;
};

/**
 * Helper: render a checkbox with text input
 */
QualityAlignment._renderCheckboxWithInput = function(container, id, label, checked, inputValue, onCheckChange, onInputChange, onRegexEdit) {
  var row = $('<div class="quality-checkbox-row"></div>').appendTo(container);
  var checkbox = $('<input type="checkbox" id="check-' + id + '">')
    .prop('checked', checked)
    .on('change', function() { onCheckChange($(this).prop('checked')); });
  $('<label></label>').append(checkbox).append(' ' + label).appendTo(row);
  var span = $('<span></span>').text($.i18n('data-quality-extension/regex-pattern')).appendTo(row);
  var input = $('<input type="text" class="quality-text-input">')
    .val(inputValue)
    .on('change', function() { onInputChange($(this).val()); })
    .appendTo(span);
  
  if (onRegexEdit) {
    $('<button class="button regex-editor-button"></button>')
      .text($.i18n('data-quality-extension/regex-editor-button'))
      .on('click', function() {
        RegexEditorDialog.show({
          pattern: input.val(),
          onApply: function(pattern) {
            input.val(pattern).trigger('change');
          }
        });
      })
      .appendTo(row);
  }
  
  return row;
};

/**
 * Handle resource config change
 */
QualityAlignment._onResourceConfigChange = function() {
  this._hasUnsavedChanges = true;
  if (this._unsavedIndicator) {
    this._unsavedIndicator.show();
  }
  this._updatePathPreview();
  if (typeof ImageQualityTab !== 'undefined') {
    ImageQualityTab._initResourceConfig();
  }
};

/**
 * Get system path separator
 */
QualityAlignment._getPathSeparator = function() {
  // Detect OS from navigator
  var isWindows = navigator.platform.indexOf('Win') !== -1;
  return isWindows ? '\\' : '/';
};

/**
 * Update path preview display
 */
QualityAlignment._updatePathPreview = function() {
  if (!this._pathPreviewSpan) return;

  var config = this._resourceConfig;
  var defaultSep = this._getPathSeparator();
  var sep = config.separator || defaultSep;
  var preview = '';

  if (config.pathFields && config.pathFields.length > 0) {
    // Build source root
    if (config.basePath) {
      preview = config.basePath;
      if (!preview.endsWith('/') && !preview.endsWith('\\')) {
        preview += sep;
      }
    }

    // Build path based on mode
    if (config.pathMode === 'template' && config.template) {
      preview += config.template.replace(/\{(\d+)\}/g, function(match, index) {
        var idx = parseInt(index);
        return idx < config.pathFields.length ? '{' + config.pathFields[idx] + '}' : match;
      });
    } else {
      preview += config.pathFields.map(function(f) { return '{' + f + '}'; }).join(sep);
    }
  } else {
    preview = $.i18n('data-quality-extension/path-not-configured');
  }

  this._pathPreviewSpan.text(preview);
};

/**
 * Show path configuration dialog (same as export-bound-assets)
 */
QualityAlignment._showPathConfigDialog = function() {
  var self = this;
  var columns = theProject.columnModel.columns;
  var defaultSep = this._getPathSeparator();

  var frame = $('<div class="dialog-frame" style="width: 750px;"></div>');
  var header = $('<div class="dialog-header"></div>')
    .text($.i18n('data-quality-extension/configure-path'))
    .appendTo(frame);
  var body = $('<div class="dialog-body"></div>').appendTo(frame);

  // Main layout: left (fields) + right (options)
  var mainTable = $('<div class="grid-layout grid-layout-for-ui layout-normal layout-full"><table role="presentation"></table></div>').appendTo(body);
  var mainTableInner = mainTable.find('table');

  // Header row
  var headerRow = $('<tr></tr>').appendTo(mainTableInner);
  $('<td></td>').text($.i18n('data-quality-extension/select-path-fields')).appendTo(headerRow);

  // Left: Field list
  var fieldListRow = $('<tr></tr>').appendTo(mainTableInner);
  var leftTd = $('<td width="30%" class="path-config-td"></td>').appendTo(fieldListRow);
  var fieldListContainer = $('<div class="path-config-fields"></div>').appendTo(leftTd);
  var fieldList = $('<ul class="path-field-list"></ul>').appendTo(fieldListContainer);

  // Pre-select fields from config and reorder
  var selectedFields = (this._resourceConfig.pathFields || []).slice();
  var columnNames = columns.map(function(c) { return c.name; });

  // First add selected fields in order, then add remaining
  var orderedColumns = [];
  selectedFields.forEach(function(name) {
    if (columnNames.indexOf(name) !== -1) {
      orderedColumns.push(name);
    }
  });
  columnNames.forEach(function(name) {
    if (orderedColumns.indexOf(name) === -1) {
      orderedColumns.push(name);
    }
  });

  orderedColumns.forEach(function(colName, idx) {
    var li = $('<li class="path-field-item"></li>').attr('data-column', colName).appendTo(fieldList);
    var checkbox = $('<input type="checkbox">')
      .attr('id', 'path-field-' + idx)
      .prop('checked', selectedFields.indexOf(colName) !== -1)
      .on('change', function() { updatePreview(); })
      .appendTo(li);
    $('<label></label>').attr('for', 'path-field-' + idx).text(colName).appendTo(li);
  });

  // Make list sortable
  fieldList.sortable({
    axis: 'y',
    cursor: 'move',
    update: function() { updatePreview(); }
  });

  // Right: Path options (moved below field list)
  var pathOptionsRow = $('<tr></tr>').appendTo(mainTableInner);
  var pathOptionsTd = $('<td width="70%"></td>').appendTo(fieldListRow);
  var optionsPane = $('<div class="path-config-options"></div>').appendTo(pathOptionsTd);
  var optionsTable = $('<div class="grid-layout layout-normal"><table role="presentation"></table></div>').appendTo(optionsPane);
  var optionsTableInner = optionsTable.find('table');

  // Path join method
  var joinRow1 = $('<tr></tr>').appendTo(optionsTableInner);
  $('<td colspan="2"></td>').text($.i18n('data-quality-extension/path-join-method')).appendTo(joinRow1);

  var joinRow2 = $('<tr></tr>').appendTo(optionsTableInner);
  var joinTd = $('<td></td>').appendTo(joinRow2);
  var joinTable = $('<div class="grid-layout layout-tightest"><table role="presentation"></table></div>').appendTo(joinTd);
  var joinTableInner = joinTable.find('table');

  // Separator option
  var sepRow = $('<tr></tr>').appendTo(joinTableInner);
  var pathMode = this._resourceConfig.pathMode || 'separator';
  $('<td width="1%"></td>').html('<input type="radio" name="path-config-mode" value="separator" id="path-mode-sep" ' + (pathMode === 'separator' ? 'checked' : '') + ' />').appendTo(sepRow);
  var sepLabelTd = $('<td></td>').appendTo(sepRow);
  $('<label for="path-mode-sep"></label>').text($.i18n('data-quality-extension/use-separator') + ' ').appendTo(sepLabelTd);
  var separatorInput = $('<input type="text" class="lightweight" size="5">')
    .val(this._resourceConfig.separator || defaultSep)
    .on('input', function() { updatePreview(); })
    .appendTo(sepLabelTd);

  // Template option
  var tplRow = $('<tr></tr>').appendTo(joinTableInner);
  $('<td width="1%"></td>').html('<input type="radio" name="path-config-mode" value="template" id="path-mode-tpl" ' + (pathMode === 'template' ? 'checked' : '') + ' />').appendTo(tplRow);
  var tplLabelTd = $('<td></td>').appendTo(tplRow);
  $('<label for="path-mode-tpl"></label>').text($.i18n('data-quality-extension/use-template') + ' ').appendTo(tplLabelTd);
  var templateInput = $('<input type="text" class="lightweight" size="30">')
    .val(this._resourceConfig.template || '')
    .attr('placeholder', '{0}/{1}/{2}')
    .on('input', function() { updatePreview(); })
    .appendTo(tplLabelTd);

  // Radio change handler
  optionsPane.find('input[name="path-config-mode"]').on('change', function() { updatePreview(); });

  // Source root path
  var rootRow1 = $('<tr></tr>').appendTo(optionsTableInner);
  $('<td colspan="2" style="padding-top: 15px;"></td>').text($.i18n('data-quality-extension/source-root-path')).appendTo(rootRow1);

  var rootRow2 = $('<tr></tr>').appendTo(optionsTableInner);
  var rootTd = $('<td></td>').appendTo(rootRow2);
  var rootTable = $('<div class="grid-layout layout-tightest"><table role="presentation"></table></div>').appendTo(rootTd);
  var rootTableInner = rootTable.find('table');
  var rootInputRow = $('<tr></tr>').appendTo(rootTableInner);
  $('<td width="100%"></td>').html('<input type="text" class="lightweight" style="width: 100%;" id="source-root-input" />').appendTo(rootInputRow);
  var sourceRootInput = rootTd.find('#source-root-input').val(this._resourceConfig.basePath || '').on('input', function() { updatePreview(); });
  $('<td width="1%"></td>').html('<button class="button">' + $.i18n('data-quality-extension/browse') + '</button>').appendTo(rootInputRow);
  rootInputRow.find('button').on('click', function() {
    var path = prompt($.i18n('data-quality-extension/enter-directory-path') || '请输入目录路径：', sourceRootInput.val());
    if (path && path.trim()) {
      sourceRootInput.val(path.trim());
      updatePreview();
    }
  });

  // Path preview
  var previewRow1 = $('<tr></tr>').appendTo(optionsTableInner);
  $('<td colspan="2" style="padding-top: 15px;"></td>').text($.i18n('data-quality-extension/path-preview')).appendTo(previewRow1);

  var previewRow2 = $('<tr></tr>').appendTo(optionsTableInner);
  var previewPane = $('<div class="path-config-preview"></div>');
  $('<td></td>').append(previewPane).appendTo(previewRow2);

  // Button row
  var buttonRow = $('<tr></tr>').appendTo(mainTableInner);
  var buttonTd = $('<td colspan="2"></td>').appendTo(buttonRow);
  $('<button class="button"></button>')
    .text($.i18n('data-quality-extension/select-all'))
    .on('click', function() {
      fieldList.find('input[type=checkbox]').prop('checked', true);
      updatePreview();
    })
    .appendTo(buttonTd);
  $('<button class="button"></button>')
    .text($.i18n('data-quality-extension/deselect-all'))
    .css('margin-left', '5px')
    .on('click', function() {
      fieldList.find('input[type=checkbox]').prop('checked', false);
      updatePreview();
    })
    .appendTo(buttonTd);

  function updatePreview() {
    var orderedFields = [];
    fieldList.find('li').each(function() {
      if ($(this).find('input[type=checkbox]').prop('checked')) {
        orderedFields.push($(this).data('column'));
      }
    });

    if (orderedFields.length === 0) {
      previewPane.text($.i18n('data-quality-extension/no-fields-selected'));
      return;
    }

    var mode = optionsPane.find('input[name="path-config-mode"]:checked').val();
    var sep = separatorInput.val() || defaultSep;
    var tpl = templateInput.val();
    var sourceRoot = sourceRootInput.val();

    var previewPath = '';
    if (sourceRoot) {
      previewPath = sourceRoot;
      if (!previewPath.endsWith('/') && !previewPath.endsWith('\\')) {
        previewPath += sep;
      }
    }

    if (mode === 'template' && tpl) {
      previewPath += tpl.replace(/\{(\d+)\}/g, function(match, index) {
        var idx = parseInt(index);
        return idx < orderedFields.length ? '{' + orderedFields[idx] + '}' : match;
      });
    } else {
      previewPath += orderedFields.map(function(f) { return '{' + f + '}'; }).join(sep);
    }

    previewPane.text(previewPath);
  }

  updatePreview();

  // Footer
  var footer = $('<div class="dialog-footer"></div>').appendTo(frame);
  $('<button class="button"></button>')
    .text($.i18n('data-quality-extension/cancel'))
    .on('click', function() { DialogSystem.dismissUntil(level - 1); })
    .appendTo(footer);
  $('<button class="button button-primary"></button>')
    .text($.i18n('data-quality-extension/confirm'))
    .on('click', function() {
      // Save config
      self._resourceConfig.basePath = sourceRootInput.val().trim();
      self._resourceConfig.pathMode = optionsPane.find('input[name="path-config-mode"]:checked').val();
      self._resourceConfig.separator = separatorInput.val() || defaultSep;
      self._resourceConfig.template = templateInput.val();
      self._resourceConfig.pathFields = [];
      fieldList.find('li').each(function() {
        if ($(this).find('input[type=checkbox]').prop('checked')) {
          self._resourceConfig.pathFields.push($(this).data('column'));
        }
      });
      self._onResourceConfigChange();
      DialogSystem.dismissUntil(level - 1);
    })
    .appendTo(footer);

  var level = DialogSystem.showDialog(frame);
};

