/*
 * Records Assets Controller - Frontend
 */

(function() {
  'use strict';

  /**
   * Records Assets Preview UI
   */
  var RecordsAssetsPreviewUI = function(options) {
    this.options = options || {};
  };

  RecordsAssetsPreviewUI.prototype.render = function(container) {
    var self = this;
    
    var html = '<div class="records-assets-preview">' +
      '<div class="assets-header">' +
      '<h3>' + i18n.t('records.assets.preview.title') + '</h3>' +
      '</div>' +
      '<div class="assets-content">' +
      '<div class="assets-browser">' +
      '<div class="assets-tree"></div>' +
      '</div>' +
      '<div class="assets-viewer">' +
      '<div class="viewer-placeholder">' +
      i18n.t('records.assets.preview.selectFile') +
      '</div>' +
      '</div>' +
      '</div>' +
      '</div>';

    $(container).html(html);
    this.setupEventHandlers();
  };

  RecordsAssetsPreviewUI.prototype.setupEventHandlers = function() {
    // Event handlers will be implemented in Task 1.6
  };

  /**
   * File List Manager
   */
  var FileListManager = function(options) {
    this.options = options || {};
    this.cache = {};
  };

  FileListManager.prototype.listFiles = function(root, path, callback) {
    var self = this;
    var cacheKey = root + ':' + (path || '');

    if (this.cache[cacheKey]) {
      callback(null, this.cache[cacheKey]);
      return;
    }

    $.ajax({
      url: '/command/records-assets/list',
      type: 'GET',
      data: {
        root: root,
        path: path || '',
        depth: 1
      },
      dataType: 'json',
      success: function(data) {
        if (data.status === 'ok') {
          self.cache[cacheKey] = data;
          callback(null, data);
        } else {
          callback(new Error(data.message || 'Unknown error'));
        }
      },
      error: function(xhr, status, error) {
        callback(new Error(error || 'Request failed'));
      }
    });
  };

  FileListManager.prototype.previewFile = function(root, path, callback) {
    $.ajax({
      url: '/command/records-assets/preview',
      type: 'GET',
      data: {
        root: root,
        path: path
      },
      dataType: 'json',
      success: function(data) {
        if (data.status === 'ok') {
          callback(null, data);
        } else {
          callback(new Error(data.message || 'Unknown error'));
        }
      },
      error: function(xhr, status, error) {
        callback(new Error(error || 'Request failed'));
      }
    });
  };

  /**
   * Export to global scope
   */
  window.RecordsAssetsPreviewUI = RecordsAssetsPreviewUI;
  window.FileListManager = FileListManager;
})();



/* ===== /extension/records-assets/scripts/project/resource-explorer.js ===== */

/*
 * Resource Explorer - Main Module
 * Manages file path column states and provides resource exploration functionality
 */

var ResourceExplorer = {};

(function() {
  'use strict';

  // Store file path column configurations
  // Key: column name, Value: { enabled: boolean, rootPath: string }
  ResourceExplorer._filePathColumns = {};

  // Local storage key for persisting configuration
  ResourceExplorer._storageKey = 'resource-explorer-columns-';

  // i18n initialized flag
  ResourceExplorer._i18nInitialized = false;

  /**
   * Initialize i18n for records-assets extension
   */
  ResourceExplorer.initI18n = function() {
    if (ResourceExplorer._i18nInitialized) {
      return;
    }

    // Load translations for records-assets module
    if (typeof I18NUtil !== 'undefined' && I18NUtil.init) {
      try {
        I18NUtil.init('records-assets');
        ResourceExplorer._i18nInitialized = true;
        console.log('[ResourceExplorer] i18n initialized for records-assets');
      } catch (e) {
        console.warn('[ResourceExplorer] Failed to initialize i18n:', e);
      }
    }
  };

  /**
   * Initialize ResourceExplorer for current project
   * Called manually or after toggle/set operations
   */
  ResourceExplorer.init = function() {
    // Initialize i18n first
    ResourceExplorer.initI18n();

    if (typeof theProject !== 'undefined' && theProject.id) {
      ResourceExplorer._loadConfig();
    }
  };

  /**
   * Get storage key for current project
   */
  ResourceExplorer._getStorageKey = function() {
    if (typeof theProject !== 'undefined' && theProject.id) {
      return ResourceExplorer._storageKey + theProject.id;
    }
    return null;
  };

  /**
   * Load configuration from localStorage
   */
  ResourceExplorer._loadConfig = function() {
    var key = ResourceExplorer._getStorageKey();
    if (key) {
      try {
        var stored = localStorage.getItem(key);
        if (stored) {
          ResourceExplorer._filePathColumns = JSON.parse(stored);
        }
      } catch (e) {
        console.error('Failed to load ResourceExplorer config:', e);
        ResourceExplorer._filePathColumns = {};
      }
    }
  };
  /**
   * 案卷著录场景下「文件夹路径」是标配列。若该项目尚无任何文件路径列配置，
   * 则把名称含「路径」的列默认标记为文件路径列，使单元格开箱即可点击查看原图，
   * 无需先在列头菜单手动勾选；已有配置的项目不受影响。
   */
  ResourceExplorer._applyDefaultColumns = function() {
    if (Object.keys(ResourceExplorer._filePathColumns).length > 0) {
      return;
    }
    if (typeof theProject === 'undefined' || !theProject.columnModel) {
      return;
    }
    var columns = theProject.columnModel.columns || [];
    var changed = false;
    columns.forEach(function(column) {
      if (column && column.name && column.name.indexOf('路径') >= 0) {
        ResourceExplorer._filePathColumns[column.name] = { enabled: true, rootPath: '' };
        changed = true;
      }
    });
    if (changed) {
      ResourceExplorer._saveConfig();
    }
  };

  /**
   * Save configuration to localStorage
   */
  ResourceExplorer._saveConfig = function() {
    var key = ResourceExplorer._getStorageKey();
    if (key) {
      try {
        localStorage.setItem(key, JSON.stringify(ResourceExplorer._filePathColumns));
      } catch (e) {
        console.error('Failed to save ResourceExplorer config:', e);
      }
    }
  };

  /**
   * Check if a column is marked as file path column
   * @param {string} columnName - Column name to check
   * @returns {boolean}
   */
  ResourceExplorer.isFilePathColumn = function(columnName) {
    var config = ResourceExplorer._filePathColumns[columnName];
    return config && config.enabled === true;
  };

  /**
   * Toggle file path column status
   * @param {string} columnName - Column name to toggle
   * @returns {boolean} New enabled state
   */
  ResourceExplorer.toggleFilePathColumn = function(columnName) {
    if (!ResourceExplorer._filePathColumns[columnName]) {
      ResourceExplorer._filePathColumns[columnName] = {
        enabled: false,
        rootPath: ''
      };
    }
    
    var config = ResourceExplorer._filePathColumns[columnName];
    config.enabled = !config.enabled;
    
    ResourceExplorer._saveConfig();
    
    // Refresh data table to update cell rendering
    if (typeof ui !== 'undefined' && ui.dataTableView) {
      ui.dataTableView.render();
    }
    
    return config.enabled;
  };

  /**
   * Set root path for a file path column
   * @param {string} columnName - Column name
   * @param {string} rootPath - Root path for file exploration
   */
  ResourceExplorer.setRootPath = function(columnName, rootPath) {
    if (!ResourceExplorer._filePathColumns[columnName]) {
      ResourceExplorer._filePathColumns[columnName] = {
        enabled: false,
        rootPath: ''
      };
    }
    ResourceExplorer._filePathColumns[columnName].rootPath = rootPath;
    ResourceExplorer._saveConfig();
  };

  /**
   * Get root path for a file path column
   * @param {string} columnName - Column name
   * @returns {string} Root path or empty string
   */
  ResourceExplorer.getRootPath = function(columnName) {
    var config = ResourceExplorer._filePathColumns[columnName];
    return config ? (config.rootPath || '') : '';
  };

  /**
   * Get all file path column names
   * @returns {string[]} Array of column names marked as file path
   */
  ResourceExplorer.getFilePathColumns = function() {
    var columns = [];
    for (var name in ResourceExplorer._filePathColumns) {
      if (ResourceExplorer._filePathColumns[name].enabled) {
        columns.push(name);
      }
    }
    return columns;
  };

  /**
   * Wait for theProject and ui.dataTableView to be available, then initialize
   */
  ResourceExplorer._waitAndInit = function() {
    // Check if theProject is available（需列模型就绪后才能判定默认文件路径列）
    if (typeof theProject === 'undefined' || !theProject.id || !theProject.columnModel) {
      setTimeout(ResourceExplorer._waitAndInit, 200);
      return;
    }

    // Initialize config
    ResourceExplorer.initI18n();
    ResourceExplorer._loadConfig();
    ResourceExplorer._applyDefaultColumns();

    // Check if we have file path columns to restore
    var hasFilePathColumns = Object.keys(ResourceExplorer._filePathColumns).some(function(name) {
      return ResourceExplorer._filePathColumns[name].enabled;
    });

    if (hasFilePathColumns) {
      // Wait for dataTableView to be ready
      ResourceExplorer._waitForDataTableAndRender();
    }
  };

  /**
   * Wait for ui.dataTableView to be ready, then trigger render
   */
  ResourceExplorer._waitForDataTableAndRender = function() {
    if (typeof ui === 'undefined' || !ui.dataTableView) {
      setTimeout(ResourceExplorer._waitForDataTableAndRender, 200);
      return;
    }

    console.log('[ResourceExplorer] Restoring file path column states, triggering re-render');
    ui.dataTableView.render();
  };

  // Initialize when document is ready
  $(document).ready(function() {
    ResourceExplorer._waitAndInit();
  });

})();



/* ===== /extension/records-assets/scripts/project/menu-file-path.js ===== */

/*
 * Menu File Path Extension
 * Adds "Extension" > "As File Path" menu to column header dropdown
 */

(function() {
  'use strict';

  /**
   * Extend column header menu with file path options
   * @param {Object} column - The column object
   * @param {Object} columnHeaderUI - The column header UI object
   * @param {Array} menu - The menu items array
   */
  function extendColumnHeaderMenu(column, columnHeaderUI, menu) {
    var columnName = column.name;
    var isFilePath = ResourceExplorer.isFilePathColumn(columnName);

    // Add separator before extension menu
    menu.push({});

    // Add "Extension" menu with "As File Path" submenu
    menu.push({
      id: "records-assets/extension",
      label: $.i18n('records.assets.menu.extension') || 'Extension',
      submenu: [
        {
          id: "records-assets/as-file-path",
          label: (isFilePath ? '✓ ' : '') + ($.i18n('records.assets.menu.asFilePath') || 'As File Path'),
          click: function() {
            var newState = ResourceExplorer.toggleFilePathColumn(columnName);
            
            // Show notification
            var message = newState 
              ? ($.i18n('records.assets.menu.filePathEnabled') || 'Column marked as file path. Click cells to explore resources.')
              : ($.i18n('records.assets.menu.filePathDisabled') || 'File path mode disabled for this column.');
            
            // Use simple alert or toast if available
            if (typeof Refine !== 'undefined' && Refine.showNotification) {
              Refine.showNotification(message);
            } else {
              console.log('[ResourceExplorer]', message);
            }
          }
        },
        {
          id: "records-assets/set-root-path",
          label: $.i18n('records.assets.menu.setRootPath') || 'Set Root Path...',
          click: function() {
            showSetRootPathDialog(columnName);
          }
        }
      ]
    });
  }

  /**
   * Show dialog to set root path for file exploration
   * @param {string} columnName - Column name
   */
  function showSetRootPathDialog(columnName) {
    var currentPath = ResourceExplorer.getRootPath(columnName);
    
    var frame = $(
      '<div class="dialog-frame">' +
        '<div class="dialog-header" id="set-root-path-header">' +
          '<span>' + ($.i18n('records.assets.menu.setRootPathTitle') || 'Set Root Path') + '</span>' +
        '</div>' +
        '<div class="dialog-body">' +
          '<p>' + ($.i18n('records.assets.menu.setRootPathDesc') || 'Enter the root path for file exploration:') + '</p>' +
          '<input type="text" class="root-path-input" style="width: 100%; padding: 8px; box-sizing: border-box;" />' +
          '<p class="dialog-hint" style="color: #666; font-size: 12px; margin-top: 8px;">' +
            ($.i18n('records.assets.menu.setRootPathHint') || 'Cell values will be treated as relative paths from this root.') +
          '</p>' +
        '</div>' +
        '<div class="dialog-footer">' +
          '<button class="button button-primary ok-button">' + ($.i18n('core-buttons/ok') || 'OK') + '</button>' +
          '<button class="button cancel-button">' + ($.i18n('core-buttons/cancel') || 'Cancel') + '</button>' +
        '</div>' +
      '</div>'
    );

    var input = frame.find('.root-path-input');
    input.val(currentPath);

    var level = DialogSystem.showDialog(frame);

    frame.find('.ok-button').on('click', function() {
      var newPath = input.val().trim();
      ResourceExplorer.setRootPath(columnName, newPath);
      DialogSystem.dismissUntil(level - 1);
    });

    frame.find('.cancel-button').on('click', function() {
      DialogSystem.dismissUntil(level - 1);
    });

    // Focus input
    input.trigger('focus');
  }

  // Register the menu extender when DataTableColumnHeaderUI is available
  function registerMenuExtender() {
    if (typeof DataTableColumnHeaderUI !== 'undefined' && 
        typeof DataTableColumnHeaderUI.extendMenu === 'function') {
      DataTableColumnHeaderUI.extendMenu(extendColumnHeaderMenu);
      console.log('[ResourceExplorer] Menu extender registered successfully');
    } else {
      // Retry after a short delay
      setTimeout(registerMenuExtender, 100);
    }
  }

  // Initialize when document is ready
  $(document).ready(function() {
    registerMenuExtender();
  });

})();



/* ===== /extension/records-assets/scripts/project/file-path-cell-renderer.js ===== */

/*
 * File Path Cell Renderer
 * Renders cells in file path columns as clickable links
 */

var FilePathCellRenderer = {};

(function() {
  'use strict';

  /**
   * FilePathCellRenderer class
   * Implements the cell renderer interface for file path columns
   */
  FilePathCellRenderer = function() {};

  /**
   * Render a cell as a clickable file path link
   * @param {number} rowIndex - Row index
   * @param {number} cellIndex - Cell index  
   * @param {Object} cell - Cell data
   * @param {Object} cellUI - Cell UI controller
   * @returns {HTMLElement|null} Rendered element or null if not applicable
   */
  FilePathCellRenderer.prototype.render = function(rowIndex, cellIndex, cell, cellUI) {
    // Get column info
    var column = Refine.cellIndexToColumn(cellIndex);
    if (!column) {
      return null;
    }

    // Check if this column is marked as file path
    if (!ResourceExplorer.isFilePathColumn(column.name)) {
      return null;
    }

    // Check if cell has a value
    if (!cell || cell.v === null || cell.v === undefined || cell.v === '') {
      return null;
    }

    var value = cell.v;
    var self = this;

    // Create the clickable element
    var container = document.createElement('div');
    container.className = 'file-path-cell-container';

    var link = document.createElement('a');
    link.href = 'javascript:void(0)';
    link.className = 'file-path-cell-link';
    link.title = $.i18n('records.assets.cell.clickToExplore') || 'Click to explore resource';
    
    // Truncate long paths for display
    var displayValue = value;
    if (displayValue.length > 50) {
      displayValue = '...' + displayValue.substring(displayValue.length - 47);
    }
    link.textContent = displayValue;

    // Add click handler
    link.addEventListener('click', function(event) {
      event.preventDefault();
      event.stopPropagation();
      self._handleCellClick(column.name, value, rowIndex);
    });

    container.appendChild(link);
    return container;
  };

  /**
   * Handle cell click - open resource explorer
   * @param {string} columnName - Column name
   * @param {string} filePath - File path value from cell
   * @param {number} rowIndex - Row index
   */
  FilePathCellRenderer.prototype._handleCellClick = function(columnName, filePath, rowIndex) {
    var rootPath = ResourceExplorer.getRootPath(columnName);
    
    console.log('[FilePathCellRenderer] Opening resource explorer:', {
      columnName: columnName,
      filePath: filePath,
      rootPath: rootPath,
      rowIndex: rowIndex
    });

    // Show resource explorer panel
    if (typeof ResourceExplorerPanel !== 'undefined') {
      ResourceExplorerPanel.show(rootPath, filePath);
    } else {
      // Fallback: show simple preview dialog
      this._showSimplePreview(rootPath, filePath);
    }
  };

  /**
   * Show simple preview dialog (fallback)
   * @param {string} rootPath - Root path
   * @param {string} filePath - Relative file path
   */
  FilePathCellRenderer.prototype._showSimplePreview = function(rootPath, filePath) {
    var fullPath = rootPath ? (rootPath + '/' + filePath) : filePath;
    
    // Request file preview from API
    $.ajax({
      url: '/command/records-assets/preview',
      type: 'GET',
      data: {
        root: rootPath,
        path: filePath
      },
      dataType: 'json',
      success: function(data) {
        if (data.status === 'ok' || data.status === 'success') {
          FilePathCellRenderer._showPreviewDialog(data, fullPath);
        } else {
          alert(data.message || $.i18n('records.assets.preview.error') || 'Error loading file');
        }
      },
      error: function(xhr, status, error) {
        console.error('[FilePathCellRenderer] Preview error:', error);
        alert($.i18n('records.assets.errors.connectionError') || 'Connection error');
      }
    });
  };

  /**
   * Show preview dialog
   * @param {Object} data - Preview data from API
   * @param {string} fullPath - Full file path
   */
  FilePathCellRenderer._showPreviewDialog = function(data, fullPath) {
    var frame = $(
      '<div class="dialog-frame file-preview-dialog">' +
        '<div class="dialog-header" id="file-preview-header">' +
          '<span class="file-preview-title">' + (data.name || fullPath) + '</span>' +
        '</div>' +
        '<div class="dialog-body file-preview-body"></div>' +
        '<div class="dialog-footer">' +
          '<button class="button cancel-button">' + ($.i18n('core-buttons/close') || 'Close') + '</button>' +
        '</div>' +
      '</div>'
    );

    var body = frame.find('.file-preview-body');
    
    // Render preview based on type
    if (data.previewType === 'image' && data.preview) {
      var img = $('<img>').attr('src', data.preview).css({
        'max-width': '100%',
        'max-height': '500px'
      });
      body.append(img);
    } else if (data.previewType === 'text' && data.preview) {
      var pre = $('<pre>').text(data.preview).css({
        'max-height': '400px',
        'overflow': 'auto'
      });
      body.append(pre);
    } else {
      body.append('<p>' + ($.i18n('records.assets.preview.noPreview') || 'Cannot preview this file') + '</p>');
    }

    var level = DialogSystem.showDialog(frame);

    frame.find('.cancel-button').on('click', function() {
      DialogSystem.dismissUntil(level - 1);
    });
  };

  /**
   * Register the renderer to CellRendererRegistry
   */
  function registerRenderer() {
    if (typeof CellRendererRegistry !== 'undefined') {
      // Insert at the beginning to have higher priority
      CellRendererRegistry.renderers.unshift({
        name: 'file-path',
        renderer: new FilePathCellRenderer()
      });
      console.log('[FilePathCellRenderer] Renderer registered successfully');
    } else {
      setTimeout(registerRenderer, 100);
    }
  }

  $(document).ready(function() {
    registerRenderer();
  });

})();



/* ===== /extension/records-assets/scripts/project/resource-explorer-panel.js ===== */

/*
 * Resource Explorer Panel
 * Left panel component for resource exploration with hierarchical tree
 */

var ResourceExplorerPanel = {};

(function() {
  'use strict';

  // Panel state
  ResourceExplorerPanel._isVisible = false;
  ResourceExplorerPanel._isActive = false; // Whether panel should be shown (not manually closed)
  ResourceExplorerPanel._currentRootPath = '';
  ResourceExplorerPanel._currentFilePath = '';
  ResourceExplorerPanel._panelElement = null;
  ResourceExplorerPanel._expandedPaths = {}; // Track expanded folders
  ResourceExplorerPanel._selectedItem = null; // Currently selected item element
  ResourceExplorerPanel._selectedPath = ''; // Currently selected item path

  /**
   * Show the resource explorer panel
   * @param {string} rootPath - Root path for exploration
   * @param {string} filePath - Initial file path to explore
   */
  ResourceExplorerPanel.show = function(rootPath, filePath) {
    ResourceExplorerPanel._currentRootPath = rootPath || '';
    ResourceExplorerPanel._currentFilePath = filePath || '';

    if (!ResourceExplorerPanel._panelElement) {
      ResourceExplorerPanel._createPanel();
    }

    // 本面板挂在左侧栏内，而 JinRefine 进入项目时默认收起左侧面板
    // （见 core/scripts/project.js）。若仍处于收起状态，面板虽被创建却不可见，
    // 用户点击单元格后界面毫无变化，会误以为"资源/图片无法查看"。故此处先展开左侧栏。
    if (typeof Refine !== 'undefined' && typeof Refine.showLeftPanel === 'function') {
      Refine.showLeftPanel();
    }

    // Show panel and hide original tabs
    ResourceExplorerPanel._panelElement.show();
    if (ui && ui.leftPanelTabs) {
      ui.leftPanelTabs.hide();
    }

    ResourceExplorerPanel._isVisible = true;
    ResourceExplorerPanel._isActive = true; // Mark as active

    var displayRoot = rootPath || filePath || '';
    if (!displayRoot && filePath) {
      var lastSlash = filePath.lastIndexOf('/');
      if (lastSlash < 0) {
        lastSlash = filePath.lastIndexOf('\\');
      }
      if (lastSlash > 0) {
        displayRoot = filePath.substring(0, lastSlash);
      }
    }

    ResourceExplorerPanel._loadAndExpandPath(displayRoot, filePath);
  };

  /**
   * Hide the resource explorer panel (close it, return to original tabs)
   */
  ResourceExplorerPanel.hide = function() {
    if (ResourceExplorerPanel._panelElement) {
      ResourceExplorerPanel._panelElement.hide();
    }

    // Show original tabs
    if (ui && ui.leftPanelTabs) {
      ui.leftPanelTabs.show();
    }

    ResourceExplorerPanel._isVisible = false;
    ResourceExplorerPanel._isActive = false; // Mark as closed
  };

  /**
   * Collapse the resource explorer panel (hide left panel, but keep active)
   */
  ResourceExplorerPanel.collapse = function() {
    ResourceExplorerPanel._isVisible = false;
    // Don't set _isActive to false - we want to restore when left panel shows again
  };

  /**
   * Restore the resource explorer panel if it was active
   */
  ResourceExplorerPanel.restore = function() {
    if (ResourceExplorerPanel._isActive && ResourceExplorerPanel._panelElement) {
      ResourceExplorerPanel._panelElement.show();
      if (ui && ui.leftPanelTabs) {
        ui.leftPanelTabs.hide();
      }
      ResourceExplorerPanel._isVisible = true;
    }
  };

  /**
   * Toggle panel visibility
   */
  ResourceExplorerPanel.toggle = function() {
    if (ResourceExplorerPanel._isVisible) {
      ResourceExplorerPanel.hide();
    } else {
      ResourceExplorerPanel.show(
        ResourceExplorerPanel._currentRootPath,
        ResourceExplorerPanel._currentFilePath
      );
    }
  };

  /**
   * Create the panel element
   */
  ResourceExplorerPanel._createPanel = function() {
    var panel = $('<div>')
      .attr('id', 'resource-explorer-panel')
      .addClass('resource-explorer-panel');

    // Header with close button
    var header = $('<div>')
      .addClass('resource-explorer-header')
      .appendTo(panel);

    $('<span>')
      .addClass('resource-explorer-title')
      .text($.i18n('records.assets.explorer.title') || 'Resource Explorer')
      .appendTo(header);

    var headerButtons = $('<div>')
      .addClass('resource-explorer-header-buttons')
      .appendTo(header);

    // Collapse button (hides left panel but keeps resource explorer active)
    $('<button>')
      .addClass('resource-explorer-collapse-btn')
      .attr('title', $.i18n('core-index/hide-panel') || 'Hide panel')
      .on('click', function() {
        ResourceExplorerPanel.collapse();
        Refine._showHideLeftPanel();
      })
      .appendTo(headerButtons);

    // Close button (returns to original tabs)
    $('<button>')
      .addClass('resource-explorer-close-btn')
      .attr('title', $.i18n('records.assets.explorer.close') || 'Close')
      .html('&times;')
      .on('click', function() {
        ResourceExplorerPanel.hide();
      })
      .appendTo(headerButtons);

    // Tree container (scrollable, focusable for keyboard scrolling)
    var treeContainer = $('<div>')
      .attr('id', 'resource-explorer-tree-container')
      .attr('tabindex', '0')
      .addClass('resource-explorer-tree-container')
      .appendTo(panel);

    // Append to left panel
    if (ui && ui.leftPanelDiv) {
      panel.appendTo(ui.leftPanelDiv);
    } else {
      panel.appendTo($('#left-panel'));
    }

    ResourceExplorerPanel._panelElement = panel;
    panel.hide();
  };

  /**
   * Load and auto-expand the initial path
   */
  ResourceExplorerPanel._loadAndExpandPath = function(rootPath, filePath) {
    var container = $('#resource-explorer-tree-container');
    container.empty();

    // Extract directory from file path
    var dirPath = filePath ? filePath.replace(/[\/\\][^\/\\]*$/, '') : '';
    if (!dirPath && filePath) {
      dirPath = filePath;
    }

    // Mark initial path as expanded
    ResourceExplorerPanel._expandedPaths[dirPath] = true;
    ResourceExplorerPanel._currentRootPath = dirPath;

    // Create root node and load its contents
    ResourceExplorerPanel._createRootNode(container, dirPath);
  };

  /**
   * Create root node with path display
   */
  ResourceExplorerPanel._createRootNode = function(container, rootPath) {
    // Path bar
    var pathBar = $('<div>')
      .addClass('resource-explorer-path-bar')
      .appendTo(container);

    $('<span>')
      .addClass('path-label')
      .text($.i18n('records.assets.list.path') || 'Path')
      .appendTo(pathBar);

    $('<span>')
      .addClass('path-value')
      .text(rootPath)
      .attr('title', rootPath)
      .appendTo(pathBar);

    // Refresh button
    $('<button>')
      .addClass('resource-explorer-refresh-btn')
      .text($.i18n('records.assets.list.refresh') || 'Refresh')
      .on('click', function() {
        ResourceExplorerPanel._expandedPaths = {};
        ResourceExplorerPanel._loadAndExpandPath('', rootPath);
      })
      .appendTo(pathBar);

    // Tree list container
    var treeList = $('<div>')
      .addClass('resource-explorer-tree-list')
      .appendTo(container);

    // Load root folder contents
    ResourceExplorerPanel._loadFolderContents(treeList, rootPath, 0);
  };

  /**
   * Load folder contents and render as tree nodes
   * @param {jQuery} container - Container to append items to
   * @param {string} folderPath - Full path to folder
   * @param {number} level - Indentation level
   */
  ResourceExplorerPanel._loadFolderContents = function(container, folderPath, level) {
    var loadingEl = $('<div>')
      .addClass('tree-loading')
      .css('padding-left', (level * 20 + 8) + 'px')
      .text($.i18n('records.assets.preview.loading') || 'Loading...')
      .appendTo(container);

    $.ajax({
      url: '/command/records-assets/list',
      type: 'GET',
      data: { root: '', path: folderPath, page: 1, pageSize: 500 },
      dataType: 'json',
      success: function(data) {
        loadingEl.remove();
        if (data.status === 'ok' || data.status === 'success') {
          var fullPath = data.fullPath || folderPath;
          ResourceExplorerPanel._renderTreeItems(container, data.items || [], fullPath, level);
        } else {
          $('<div>')
            .addClass('tree-error')
            .css('padding-left', (level * 20 + 8) + 'px')
            .text(data.message || 'Error')
            .appendTo(container);
        }
      },
      error: function() {
        loadingEl.remove();
        $('<div>')
          .addClass('tree-error')
          .css('padding-left', (level * 20 + 8) + 'px')
          .text($.i18n('records.assets.errors.connectionError') || 'Error')
          .appendTo(container);
      }
    });
  };

  /**
   * Render tree items with proper hierarchy
   */
  ResourceExplorerPanel._renderTreeItems = function(container, items, parentPath, level) {
    if (items.length === 0) {
      $('<div>')
        .addClass('tree-empty')
        .css('padding-left', (level * 20 + 8) + 'px')
        .text($.i18n('records.assets.list.empty') || 'Empty folder')
        .appendTo(container);
      return;
    }

    // Sort: folders first, then files
    items.sort(function(a, b) {
      if (a.isDirectory && !b.isDirectory) return -1;
      if (!a.isDirectory && b.isDirectory) return 1;
      return a.name.localeCompare(b.name);
    });

    items.forEach(function(item) {
      var itemFullPath = parentPath + '/' + item.name;
      var isExpanded = ResourceExplorerPanel._expandedPaths[itemFullPath];

      // Create item row
      var itemRow = $('<div>')
        .addClass('tree-item')
        .addClass(item.isDirectory ? 'tree-folder' : 'tree-file')
        .css('padding-left', (level * 20) + 'px')
        .appendTo(container);

      // Expand/collapse toggle for folders
      var toggleIcon = $('<span>')
        .addClass('tree-toggle')
        .text(item.isDirectory ? (isExpanded ? '▼' : '▶') : ' ')
        .appendTo(itemRow);

      // Item icon
      var iconSpan = $('<span>').addClass('tree-icon').appendTo(itemRow);
      if (item.isDirectory) {
        iconSpan.text('📁');
      } else {
        iconSpan.html(ResourceExplorerPanel._getFileIcon(item.name));
      }

      // Item name
      $('<span>')
        .addClass('tree-name')
        .text(item.name)
        .attr('title', itemFullPath)
        .appendTo(itemRow);

      // Children container for folders
      var childrenContainer = null;
      if (item.isDirectory) {
        childrenContainer = $('<div>')
          .addClass('tree-children')
          .appendTo(container);

        if (isExpanded) {
          childrenContainer.show();
          ResourceExplorerPanel._loadFolderContents(childrenContainer, itemFullPath, level + 1);
        } else {
          childrenContainer.hide();
        }
      }

      // Click handler
      itemRow.on('click', function(e) {
        e.stopPropagation();
        // Always select the clicked item
        ResourceExplorerPanel._selectItem(itemRow, itemFullPath);

        if (item.isDirectory) {
          ResourceExplorerPanel._toggleFolder(itemFullPath, toggleIcon, childrenContainer, level + 1);
        } else {
          ResourceExplorerPanel._onFileClick(itemFullPath, item);
        }
      });
    });
  };

  /**
   * Toggle folder expand/collapse
   */
  ResourceExplorerPanel._toggleFolder = function(folderPath, toggleIcon, childrenContainer, level) {
    var isExpanded = ResourceExplorerPanel._expandedPaths[folderPath];

    if (isExpanded) {
      // Collapse
      ResourceExplorerPanel._expandedPaths[folderPath] = false;
      toggleIcon.text('▶');
      childrenContainer.slideUp(150);
    } else {
      // Expand
      ResourceExplorerPanel._expandedPaths[folderPath] = true;
      toggleIcon.text('▼');
      childrenContainer.empty().show();
      ResourceExplorerPanel._loadFolderContents(childrenContainer, folderPath, level);
    }
  };

  /**
   * Get file icon based on extension
   * 返回 <img> HTML 标签
   */
  ResourceExplorerPanel._getFileIcon = function(filename) {
    var ext = filename.split('.').pop().toLowerCase();
    // 用相对路径（而非根相对 "/images/..."），以便在外壳反代下经 <base> 解析到 /or-proxy/images/...；
    // 根相对路径会绕过 base 直指外壳域，导致 404（图标全裂）。
    var basePath = 'images/extensions/';
    var iconMap = {
      // 图片类型
      'jpg': 'file-image.svg', 'jpeg': 'file-image.svg', 'png': 'file-image.svg',
      'gif': 'file-image.svg', 'bmp': 'file-image.svg', 'svg': 'file-image.svg',
      'webp': 'file-image.svg', 'ico': 'file-image.svg', 'tiff': 'file-image.svg',
      // PDF
      'pdf': 'file-pdf.svg',
      // Word 文档
      'doc': 'file-word.svg', 'docx': 'file-word.svg', 'odt': 'file-word.svg', 'rtf': 'file-word.svg',
      // Excel 表格
      'xls': 'file-excel.svg', 'xlsx': 'file-excel.svg', 'csv': 'file-excel.svg', 'ods': 'file-excel.svg',
      // 文本文件
      'txt': 'file-text.svg', 'md': 'file-text.svg', 'json': 'file-text.svg',
      'xml': 'file-text.svg', 'html': 'file-text.svg', 'htm': 'file-text.svg',
      'css': 'file-text.svg', 'js': 'file-text.svg', 'log': 'file-text.svg',
      // 压缩文件
      'zip': 'file-zipper.svg', 'rar': 'file-zipper.svg', '7z': 'file-zipper.svg',
      'tar': 'file-zipper.svg', 'gz': 'file-zipper.svg', 'bz2': 'file-zipper.svg',
      // 视频
      'mp4': 'file-video.svg', 'avi': 'file-video.svg', 'mov': 'file-video.svg',
      'mkv': 'file-video.svg', 'wmv': 'file-video.svg', 'flv': 'file-video.svg', 'webm': 'file-video.svg',
      // 音频
      'mp3': 'file-audio.svg', 'wav': 'file-audio.svg', 'flac': 'file-audio.svg',
      'aac': 'file-audio.svg', 'ogg': 'file-audio.svg', 'wma': 'file-audio.svg', 'm4a': 'file-audio.svg'
    };
    var iconFile = iconMap[ext] || 'file-text.svg';
    return '<img src="' + basePath + iconFile + '" class="file-type-icon" alt="" />';
  };

  /**
   * Handle file click - show preview
   */
  ResourceExplorerPanel._onFileClick = function(fileFullPath, item) {
    if (typeof FilePreviewDialog !== 'undefined') {
      var lastSlash = fileFullPath.lastIndexOf('/');
      if (lastSlash < 0) {
        lastSlash = fileFullPath.lastIndexOf('\\');
      }
      
      var rootPath, filePath;
      if (lastSlash > 0) {
        rootPath = fileFullPath.substring(0, lastSlash);
        filePath = fileFullPath.substring(lastSlash + 1);
      } else {
        rootPath = '';
        filePath = fileFullPath;
      }
      
      FilePreviewDialog.show(rootPath, filePath, item);
    } else {
      console.log('[ResourceExplorerPanel] FilePreviewDialog not available for:', fileFullPath);
    }
  };

  /**
   * Select an item (highlight it)
   */
  ResourceExplorerPanel._selectItem = function(itemElement, itemPath) {
    // Remove previous selection
    if (ResourceExplorerPanel._selectedItem) {
      ResourceExplorerPanel._selectedItem.removeClass('tree-item-selected');
    }

    // Set new selection
    ResourceExplorerPanel._selectedItem = itemElement;
    ResourceExplorerPanel._selectedPath = itemPath;

    if (itemElement) {
      itemElement.addClass('tree-item-selected');

      // Scroll into view if needed
      var container = $('#resource-explorer-tree-container');
      var containerTop = container.scrollTop();
      var containerHeight = container.height();
      var itemTop = itemElement.position().top + containerTop;
      var itemHeight = itemElement.outerHeight();

      if (itemTop < containerTop) {
        container.scrollTop(itemTop);
      } else if (itemTop + itemHeight > containerTop + containerHeight) {
        container.scrollTop(itemTop + itemHeight - containerHeight);
      }
    }
  };

  /**
   * Get all visible tree items in order
   */
  ResourceExplorerPanel._getVisibleItems = function() {
    return $('#resource-explorer-tree-container .tree-item:visible');
  };

  /**
   * Navigate to previous item (left arrow)
   */
  ResourceExplorerPanel._navigatePrevious = function() {
    var items = ResourceExplorerPanel._getVisibleItems();
    if (items.length === 0) return;

    var currentIndex = -1;
    if (ResourceExplorerPanel._selectedItem) {
      items.each(function(index) {
        if ($(this).is(ResourceExplorerPanel._selectedItem)) {
          currentIndex = index;
          return false;
        }
      });
    }

    var newIndex = currentIndex > 0 ? currentIndex - 1 : items.length - 1;
    var newItem = $(items[newIndex]);
    var itemPath = newItem.find('.tree-name').attr('title') || '';

    ResourceExplorerPanel._selectItem(newItem, itemPath);

    // If it's a file, open preview
    if (newItem.hasClass('tree-file')) {
      var filename = newItem.find('.tree-name').text();
      ResourceExplorerPanel._onFileClick(itemPath, { name: filename });
    }
  };

  /**
   * Navigate to next item (right arrow)
   */
  ResourceExplorerPanel._navigateNext = function() {
    var items = ResourceExplorerPanel._getVisibleItems();
    if (items.length === 0) return;

    var currentIndex = -1;
    if (ResourceExplorerPanel._selectedItem) {
      items.each(function(index) {
        if ($(this).is(ResourceExplorerPanel._selectedItem)) {
          currentIndex = index;
          return false;
        }
      });
    }

    var newIndex = currentIndex < items.length - 1 ? currentIndex + 1 : 0;
    var newItem = $(items[newIndex]);
    var itemPath = newItem.find('.tree-name').attr('title') || '';

    ResourceExplorerPanel._selectItem(newItem, itemPath);

    // If it's a file, open preview
    if (newItem.hasClass('tree-file')) {
      var filename = newItem.find('.tree-name').text();
      ResourceExplorerPanel._onFileClick(itemPath, { name: filename });
    }
  };

  /**
   * Handle keyboard events
   */
  ResourceExplorerPanel._handleKeyDown = function(e) {
    // Only handle when panel is visible
    if (!ResourceExplorerPanel._isVisible) return;

    // Only handle left/right arrows, don't interfere with other keys
    // Left arrow - previous item
    if (e.keyCode === 37) {
      e.preventDefault();
      ResourceExplorerPanel._navigatePrevious();
    }
    // Right arrow - next item
    else if (e.keyCode === 39) {
      e.preventDefault();
      ResourceExplorerPanel._navigateNext();
    }
    // Enter - toggle folder or open file (only when item selected)
    else if (e.keyCode === 13 && ResourceExplorerPanel._selectedItem) {
      e.preventDefault();
      ResourceExplorerPanel._selectedItem.trigger('click');
    }
    // Don't prevent default for up/down arrows - let them scroll normally
  };

  // Register keyboard event handler
  $(document).on('keydown', ResourceExplorerPanel._handleKeyDown);

  // Monitor left panel visibility changes using MutationObserver
  $(document).ready(function() {
    var body = document.querySelector('div#body');
    if (body) {
      var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
          if (mutation.attributeName === 'class') {
            var isHidden = body.classList.contains('hide-left-panel');
            if (!isHidden && ResourceExplorerPanel._isActive) {
              // Left panel is now visible, restore resource explorer
              ResourceExplorerPanel.restore();
            }
          }
        });
      });

      observer.observe(body, { attributes: true });
    }
  });

})();



/* ===== /extension/records-assets/scripts/project/file-preview-dialog.js ===== */

/*
 * File Preview Dialog
 * Fixed-position dialog for previewing file contents (images, PDFs, text)
 * Positioned at right edge, aligned with rightPanelDiv
 */

var FilePreviewDialog = {};

(function() {
  'use strict';

  FilePreviewDialog._currentDialog = null;
  FilePreviewDialog._zoomLevel = 1;
  FilePreviewDialog._originalPaddingRight = null;
  FilePreviewDialog._isDraggingImage = false;
  FilePreviewDialog._dragStartX = 0;
  FilePreviewDialog._dragStartY = 0;
  FilePreviewDialog._currentOffsetX = 0;
  FilePreviewDialog._currentOffsetY = 0;
  FilePreviewDialog._dragNamespace = '.imageDrag_' + Math.random().toString(36).substr(2, 9);

  /**
   * Show file preview dialog
   * @param {string} rootPath - Root path
   * @param {string} filePath - File path
   * @param {Object} fileItem - File item data
   */
  FilePreviewDialog.show = function(rootPath, filePath, fileItem) {
    // Save dragged state if dialog exists
    var wasDragged = false;
    var lastPosition = null;
    if (FilePreviewDialog._currentDialog) {
      wasDragged = FilePreviewDialog._currentDialog.data('dragged') || false;
      if (wasDragged) {
        lastPosition = {
          left: FilePreviewDialog._currentDialog.css('left'),
          top: FilePreviewDialog._currentDialog.css('top'),
          width: FilePreviewDialog._currentDialog.css('width'),
          height: FilePreviewDialog._currentDialog.css('height')
        };
      }
      FilePreviewDialog._currentDialog.remove();
    }

    // Reset zoom level
    FilePreviewDialog._zoomLevel = 1;
    
    // Reset annotation state
    FilePreviewDialog._showAnnotations = false;
    FilePreviewDialog._currentErrors = [];

    var dialog = $('<div>')
      .addClass('file-preview-dialog-float')
      .appendTo('body');

    // Header
    var header = $('<div>')
      .addClass('file-preview-float-header')
      .appendTo(dialog);

    var fileName = fileItem ? fileItem.name : filePath.split('/').pop();
    $('<span>')
      .addClass('file-preview-float-title')
      .text(fileName)
      .attr('title', filePath)
      .appendTo(header);

    $('<button>')
      .addClass('file-preview-float-close-btn')
      .html('&times;')
      .on('click', function() {
        FilePreviewDialog.close();
      })
      .appendTo(header);

    // Content container
    var content = $('<div>')
      .addClass('file-preview-float-content')
      .appendTo(dialog);

    content.html('<div class="loading">' + ($.i18n('records.assets.preview.loading') || 'Loading...') + '</div>');

    // Footer with actions
    var footer = $('<div>')
      .addClass('file-preview-float-footer')
      .appendTo(dialog);

    // Position dialog: right edge of screen, aligned with rightPanelDiv
    if (wasDragged && lastPosition) {
      dialog.css({
        left: lastPosition.left,
        top: lastPosition.top,
        right: 'auto',
        width: lastPosition.width,
        height: lastPosition.height
      });
      dialog.data('dragged', true);
    } else {
      FilePreviewDialog._positionDialog(dialog);
      dialog.data('dragged', false);
    }

    // Adjust data table container to allow scrolling past the preview panel
    FilePreviewDialog._adjustDataTablePadding(dialog);

    // Make draggable by header
    FilePreviewDialog._makeDraggable(dialog, header);

    // Handle window resize (only if not dragged)
    $(window).on('resize.filePreview', function() {
      if (!dialog.data('dragged')) {
        FilePreviewDialog._positionDialog(dialog);
      }
    });

    // Handle ESC key to close dialog
    $(document).on('keydown.filePreview', function(e) {
      if (e.keyCode === 27) { // ESC key
        e.preventDefault();
        FilePreviewDialog.close();
      }
    });

    FilePreviewDialog._currentDialog = dialog;

    // Load file preview
    FilePreviewDialog._loadPreview(rootPath, filePath, content, footer);
  };

  /**
   * Show file preview dialog with error annotations
   * @param {string} filePath - Full file path (root + path)
   * @param {Array} errors - Array of error objects with location data
   */
  FilePreviewDialog.showWithAnnotations = function(filePath, errors) {
    var self = this;
    
    var lastSlash = filePath.lastIndexOf('/');
    var rootPath = lastSlash > 0 ? filePath.substring(0, lastSlash) : '';
    var pathOnly = lastSlash > 0 ? filePath.substring(lastSlash + 1) : filePath;
    
    this.show(rootPath, pathOnly, null);
    
    this._currentErrors = errors || [];
    this._showAnnotations = errors && errors.length > 0;
    
    var checkAnnotationInterval = setInterval(function() {
      if (FilePreviewDialog._currentDialog && FilePreviewDialog._currentDialog.find('.preview-image').length > 0) {
        clearInterval(checkAnnotationInterval);
        FilePreviewDialog._updateAnnotationToggle(errors);
      }
    }, 100);
    
    setTimeout(function() {
      clearInterval(checkAnnotationInterval);
    }, 5000);
  };
  
  FilePreviewDialog._updateAnnotationToggle = function(errors) {
    var footer = FilePreviewDialog._currentDialog.find('.file-preview-float-footer');
    if (footer.length === 0) return;
    
    var actions = footer.find('.file-actions');
    if (actions.length === 0) return;
    
    var existingToggle = actions.find('.annotation-toggle-btn');
    if (existingToggle.length > 0) {
      existingToggle.remove();
    }
    
    var toggleBtn = $('<button>')
      .addClass('button annotation-toggle-btn')
      .text(FilePreviewDialog._showAnnotations ? '隐藏标注' : '显示标注')
      .on('click', function() {
        FilePreviewDialog._showAnnotations = !FilePreviewDialog._showAnnotations;
        $(this).text(FilePreviewDialog._showAnnotations ? '隐藏标注' : '显示标注');
        FilePreviewDialog._renderAnnotations();
      });
    
    actions.find('.button:last').before(toggleBtn);
    
    if (errors && errors.length > 0) {
      FilePreviewDialog._currentErrors = errors;
      FilePreviewDialog._renderAnnotations();
    }
  };
  
  FilePreviewDialog._renderAnnotations = function() {
    if (!FilePreviewDialog._currentDialog) return;
    
    var imgContainer = FilePreviewDialog._currentDialog.find('.image-preview-container');
    if (imgContainer.length === 0) return;
    
    imgContainer.find('.error-marker, .annotation-legend, .annotation-tooltip').remove();
    
    if (!FilePreviewDialog._showAnnotations || !FilePreviewDialog._currentErrors || FilePreviewDialog._currentErrors.length === 0) {
      return;
    }
    
    var img = imgContainer.find('.preview-image');
    if (img.length === 0) return;
    
    var renderMarkers = function() {
      var naturalWidth = img[0].naturalWidth;
      var naturalHeight = img[0].naturalHeight;
      
      // console.log('[FilePreviewDialog] 图像尺寸检查 - naturalWidth:', naturalWidth, 'naturalHeight:', naturalHeight);
      
      if (!naturalWidth || !naturalHeight || naturalWidth === 0 || naturalHeight === 0) {
        // console.log('[FilePreviewDialog] 图像未加载完成，等待100ms后重试');
        setTimeout(renderMarkers, 100);
        return;
      }
      
      var displayedWidth = img.width();
      var displayedHeight = img.height();
      
      var scaleX = displayedWidth / naturalWidth;
      var scaleY = displayedHeight / naturalHeight;
      
      scaleX *= FilePreviewDialog._zoomLevel;
      scaleY *= FilePreviewDialog._zoomLevel;
      
      var containerWidth = imgContainer.width();
      var containerHeight = imgContainer.height();
      
      var imgOffset = img.offset();
      var containerOffset = imgContainer.offset();
      
      var offsetX = imgOffset.left - containerOffset.left;
      var offsetY = imgOffset.top - containerOffset.top;
      
      // 考虑缩放对偏移量的影响
      // transform-origin: top left，所以缩放后图片的左上角位置不变
      // 但是图片的实际显示尺寸会改变，需要使用 getBoundingClientRect 获取实际尺寸
      var imgRect = img[0].getBoundingClientRect();
      var containerRect = imgContainer[0].getBoundingClientRect();
      
      // 计算图片相对于容器的实际位置（考虑缩放）
      // getBoundingClientRect 返回的是相对于视口的位置，需要减去容器的位置
      var actualOffsetX = imgRect.left - containerRect.left;
      var actualOffsetY = imgRect.top - containerRect.top;
      
      // 考虑容器的滚动位置
      // 当容器滚动时，图片相对于容器的位置会改变
      actualOffsetX += imgContainer.scrollLeft();
      actualOffsetY += imgContainer.scrollTop();
      
      // 使用实际偏移量
      offsetX = actualOffsetX;
      offsetY = actualOffsetY;
      
      // 手动调整偏移量 - 视觉上发现的偏移
      offsetX += -5;   // 横向往左偏移5px
      offsetY += -5;  // 纵向往上偏移5px
      
      // console.log('[FilePreviewDialog] 缩放信息 - zoomLevel:', FilePreviewDialog._zoomLevel,
                  // 'displayedWidth:', displayedWidth, 'displayedHeight:', displayedHeight,
                  // 'imgRect.width:', imgRect.width, 'imgRect.height:', imgRect.height,
                  // 'offsetX:', offsetX.toFixed(1), 'offsetY:', offsetY.toFixed(1),
                  // 'scaleX:', scaleX.toFixed(3), 'scaleY:', scaleY.toFixed(3),
                  // 'scrollLeft:', imgContainer.scrollLeft(), 'scrollTop:', imgContainer.scrollTop());
      
      var contentDiv = FilePreviewDialog._currentDialog.find('.file-preview-float-content');
      var contentOffset = contentDiv.offset();
      var contentPaddingTop = parseInt(contentDiv.css('padding-top')) || 0;
      var contentPaddingBottom = parseInt(contentDiv.css('padding-bottom')) || 0;
      
      var headerDiv = FilePreviewDialog._currentDialog.find('.file-preview-float-header');
      var headerHeight = headerDiv.outerHeight();
      var headerPaddingTop = parseInt(headerDiv.css('padding-top')) || 0;
      var headerPaddingBottom = parseInt(headerDiv.css('padding-bottom')) || 0;
      
      // console.log('[FilePreviewDialog] 布局详情:');
      // console.log('  headerHeight:', headerHeight, 'headerPadding:', headerPaddingTop, '+', headerPaddingBottom);
      // console.log('  contentPaddingTop:', contentPaddingTop, 'contentPaddingBottom:', contentPaddingBottom);
      console.log('  contentOffset.top:', contentOffset.top);
      console.log('  imgOffset.top:', imgOffset.top);
      console.log('  containerOffset.top:', containerOffset.top);
      
      // console.log('[FilePreviewDialog] 标注计算 - natural:', naturalWidth, 'x', naturalHeight, 
                  // 'displayed:', displayedWidth, 'x', displayedHeight,
                  // 'container:', containerWidth, 'x', containerHeight,
                  // 'scale:', scaleX.toFixed(3), 'x', scaleY.toFixed(3),
                  // 'offset:', offsetX.toFixed(1), ',', offsetY.toFixed(1));
      
      var legendHtml = '<div class="annotation-legend" style="display: none;">';
      var errorTypes = {};
      var nonLocationErrors = {};
    
    FilePreviewDialog._currentErrors.forEach(function(error, index) {
      if (!error.locationX && !error.locationY) {
        var nonLocationType = error.errorType;
        if (!nonLocationErrors[nonLocationType]) {
          nonLocationErrors[nonLocationType] = { count: 0, extractedValue: error.extractedValue, message: error.message || '' };
        }
        nonLocationErrors[nonLocationType].count++;
        return;
      }
      
      var markerClass = 'error-marker-';
      var legendClass = '';
      var extractedValue = '';
      
      if (error.errorType === 'stainValue' || error.errorType === 'stain') {
        markerClass += 'stain';
        legendClass = 'stain';
      } else if (error.errorType === 'hole') {
        markerClass += 'hole';
        legendClass = 'hole';
      } else if (error.errorType === 'edgeRemove' || error.errorType === 'edge') {
        markerClass += 'edge';
        legendClass = 'edge';
      } else if (error.errorType === 'bias' || error.errorType === 'bias') {
        markerClass += 'bias';
        legendClass = 'bias';
      } else {
        markerClass += 'other';
        legendClass = 'other';
      }
      
      // Count errors by type
      if (!errorTypes[legendClass]) {
        errorTypes[legendClass] = { count: 0, label: '', extractedValue: '' };
      }
      errorTypes[legendClass].count++;
      if (extractedValue) {
        errorTypes[legendClass].extractedValue = extractedValue;
      }
      
      var x = (error.locationX || 0) * scaleX + offsetX;
      var y = (error.locationY || 0) * scaleY + offsetY;
      var width = (error.locationWidth || 100) * scaleX;
      var height = (error.locationHeight || 100) * scaleY;
      
      // console.log('[FilePreviewDialog] 标注位置 - type:', error.errorType, 
                    // '原始位置:', (error.locationX || 0), ',', (error.locationY || 0),
                    // '原始尺寸:', (error.locationWidth || 100), 'x', (error.locationHeight || 100),
                    // '计算位置:', x.toFixed(1), ',', y.toFixed(1),
                    // '计算尺寸:', width.toFixed(1), 'x', height.toFixed(1));
      
      width = Math.max(width, 10);
      height = Math.max(height, 10);
      
      var marker = $('<div class="error-marker ' + markerClass + '"></div>');
      marker.css({
        left: x + 'px',
        top: y + 'px',
        width: width + 'px',
        height: height + 'px',
        position: 'absolute',
        zIndex: 1000
      });
      
      var errorLabel = error.errorType || 'error';
      var translatedLabel = errorLabel;
      if (errorLabel === 'stain' || errorLabel === 'stainValue') {
        translatedLabel = $.i18n('records.assets.annotation.stain') || '污点';
      } else if (errorLabel === 'hole') {
        translatedLabel = $.i18n('records.assets.annotation.hole') || '装订孔';
      } else if (errorLabel === 'edge' || errorLabel === 'edgeRemove') {
        translatedLabel = $.i18n('records.assets.annotation.edge') || '黑边';
      } else if (errorLabel === 'bias' || errorLabel === 'bias') {
        translatedLabel = $.i18n('records.assets.annotation.bias') || '偏斜';
      } else {
        translatedLabel = $.i18n('records.assets.annotation.other') || '其他';
      }
      
      // if (error.message) {
      //   marker.attr('title', translatedLabel + ': ' + error.message);
      // } else {
      //   marker.attr('title', translatedLabel);
      // }
      
      marker.on('mouseenter', function(e) {
        var tooltip = imgContainer.find('.annotation-tooltip');
        if (tooltip.length === 0) {
          tooltip = $('<div class="annotation-tooltip"></div>').appendTo(imgContainer);
        }
        tooltip.html('<div class="tooltip-title">' + (translatedLabel) + '</div>' +
                     '<div class="tooltip-message">' + (error.message || '') + '</div>');
        tooltip.css({
          left: (x + width + 10) + 'px',
          top: y + 'px',
          display: 'block'
        });
      });
      
      marker.on('mouseleave', function() {
        imgContainer.find('.annotation-tooltip').hide();
      });
      
      imgContainer.append(marker);
      
      if (!errorTypes[legendClass].label) {
        var typeLabel;
        if (legendClass === 'stain') {
          typeLabel = $.i18n('records.assets.annotation.stain') || '污点';
        } else if (legendClass === 'hole') {
          typeLabel = $.i18n('records.assets.annotation.hole') || '装订孔';
        } else if (legendClass === 'edge') {
          typeLabel = $.i18n('records.assets.annotation.edge') || '黑边';
        } else {
          typeLabel = $.i18n('records.assets.annotation.other') || '其他';
        }
        errorTypes[legendClass].label = typeLabel;
      }
    });
    
    // Build legend HTML with counts
    Object.keys(errorTypes).forEach(function(legendClass) {
      var typeInfo = errorTypes[legendClass];
      var typeLabel = typeInfo.label || '其他';
      var count = typeInfo.count || 0;
      
      legendHtml += '<div class="annotation-legend-item">' +
                    '<div class="annotation-legend-color annotation-legend-' + legendClass + '"></div>' +
                    '<span>' + typeLabel + '(' + count + ')</span></div>';
    });
    
    // Add non-location errors to legend
    Object.keys(nonLocationErrors).forEach(function(errorType) {
      var errorInfo = nonLocationErrors[errorType];
      var count = errorInfo.count || 0;
      var extractedValue = errorInfo.extractedValue || '';
      var label = '';
      
      switch (errorType) {
        case 'dpi':
          label = 'DPI';
          break;
        case 'file-size':
        case 'kb':
          label = '文件大小';
          break;
        case 'quality':
          label = 'JPEG质量';
          break;
        case 'bit_depth':
          label = '位深度';
          break;
        case 'repeat_image':
          label = '重复图片';
          break;
        case 'blank':
          label = '空白图片';
          break;
        case 'bias':
          label = '倾斜';
          var angleMatch = (errorInfo.message || '').match(/angle: ([-]?\d+(?:\.\d+)?)/);
          if (angleMatch) {
            errorInfo.extractedValue = angleMatch[1] + '°';
          }
          break;
        default:
          label = errorType;
      }
      
      extractedValue = errorInfo.extractedValue || '';
      
      legendHtml += '<div class="annotation-legend-item annotation-legend-nonlocation">' +
                    '<span class="annotation-legend-dot">·</span>' +
                    '<span>' + label;
      if (extractedValue) {
        legendHtml += '(' + extractedValue + ')';
      }
      legendHtml += '</span></div>';
    });
    
    legendHtml += '</div>';
    
    if (Object.keys(errorTypes).length > 0 || Object.keys(nonLocationErrors).length > 0) {
      var errorTypeTitle = $.i18n('records.assets.annotation.errorType') || '错误类型';
      var legend = $(legendHtml);
      legend.prepend('<div class="annotation-legend-title">' + errorTypeTitle + '</div>');
      imgContainer.append(legend);
      legend.fadeIn(200);
      
      FilePreviewDialog._makeDraggable(legend, legend);
    }
    };
    
    renderMarkers();
  };

  /**
   * Close the file preview dialog
   */
  FilePreviewDialog.close = function() {
    if (FilePreviewDialog._currentDialog) {
      FilePreviewDialog._currentDialog.remove();
      FilePreviewDialog._currentDialog = null;
      $(window).off('resize.filePreview');
      $(document).off('keydown.filePreview');
      $(document).off('mousemove.filePreviewDrag');
      $(document).off('mouseup.filePreviewDrag');

      // Restore data table container padding
      FilePreviewDialog._restoreDataTablePadding();
    }
  };

  /**
   * Adjust data table container padding to allow scrolling past the preview panel
   */
  FilePreviewDialog._adjustDataTablePadding = function(dialog) {
    var dataTableContainer = $('.data-table-container');
    if (dataTableContainer.length === 0) return;

    // Save original padding-right
    if (FilePreviewDialog._originalPaddingRight === null) {
      FilePreviewDialog._originalPaddingRight = dataTableContainer.css('padding-right') || '0px';
    }

    // Get dialog width
    var dialogWidth = dialog.outerWidth() || 700;

    // Add padding-right to data table container so content can scroll past the preview
    dataTableContainer.css('padding-right', (dialogWidth + 10) + 'px');
  };

  /**
   * Restore data table container padding when preview is closed
   */
  FilePreviewDialog._restoreDataTablePadding = function() {
    var dataTableContainer = $('.data-table-container');
    if (dataTableContainer.length === 0) return;

    // Restore original padding
    if (FilePreviewDialog._originalPaddingRight !== null) {
      dataTableContainer.css('padding-right', FilePreviewDialog._originalPaddingRight);
      FilePreviewDialog._originalPaddingRight = null;
    }
  };

  /**
   * Position dialog: right edge of screen, same height as rightPanelDiv
   */
  FilePreviewDialog._positionDialog = function(dialog) {
    var rightPanel = $('#right-panel');
    var viewportWidth = $(window).width();

    // Get rightPanel position and dimensions
    var panelTop = 0;
    var panelHeight = $(window).height();

    if (rightPanel.length > 0) {
      var offset = rightPanel.offset();
      panelTop = offset.top;
      panelHeight = rightPanel.outerHeight();
    }

    // Dialog width - responsive
    var dialogWidth = Math.min(700, viewportWidth * 0.4);

    dialog.css({
      top: panelTop + 'px',
      right: '0px',
      left: 'auto',
      width: dialogWidth + 'px',
      height: panelHeight + 'px'
    });
  };

  /**
   * Make element draggable by header
   */
  FilePreviewDialog._makeDraggable = function(element, handle) {
    var isDragging = false;
    var startX, startY, startLeft, startTop;
    var dragNamespace = '.drag_' + Math.random().toString(36).substr(2, 9);

    handle.css('cursor', 'move');

    handle.on('mousedown' + dragNamespace, function(e) {
      if ($(e.target).is('button')) return;
      isDragging = true;
      startX = e.clientX;
      startY = e.clientY;

      var position = element.position();
      startLeft = position.left;
      startTop = position.top;

      e.preventDefault();
    });

    $(document).on('mousemove' + dragNamespace, function(e) {
      if (!isDragging) return;

      var newLeft = startLeft + e.clientX - startX;
      var newTop = startTop + e.clientY - startY;

      element.css({
        left: newLeft + 'px',
        top: newTop + 'px',
        right: 'auto'
      });

      element.data('dragged', true);
    });

    $(document).on('mouseup' + dragNamespace, function() {
      isDragging = false;
    });
    
    element.on('remove', function() {
      $(document).off(dragNamespace);
      handle.off(dragNamespace);
    });
  };

  /**
   * Load file preview
   */
  FilePreviewDialog._loadPreview = function(rootPath, filePath, container, footer) {
    console.log('[FilePreviewDialog._loadPreview] 接收参数:');
    console.log('  rootPath:', rootPath);
    console.log('  filePath:', filePath);
    console.log('  rootPath类型:', typeof rootPath);
    console.log('  filePath类型:', typeof filePath);
    
    $.ajax({
      url: '/command/records-assets/preview',
      type: 'GET',
      data: { root: rootPath, path: filePath },
      dataType: 'json',
      success: function(data) {
        console.log('[FilePreviewDialog._loadPreview] AJAX成功返回:', data);
        if (data.status === 'ok' || data.status === 'success') {
          FilePreviewDialog._renderPreview(container, data, rootPath, filePath);
          FilePreviewDialog._renderFooter(footer, data, rootPath, filePath);
        } else {
          console.log('[FilePreviewDialog._loadPreview] 返回状态不是ok:', data.status);
          container.html('<div class="error">' + (data.message || 'Error') + '</div>');
        }
      },
      error: function(xhr, status, error) {
        console.log('[FilePreviewDialog._loadPreview] AJAX错误:', status, error);
        container.html('<div class="error">' + ($.i18n('records.assets.errors.connectionError') || 'Error') + '</div>');
      }
    });
  };

  /**
   * Render file preview content
   */
  FilePreviewDialog._renderPreview = function(container, data, rootPath, filePath) {
    container.empty();

    var previewType = data.previewType || 'unknown';
    var preview = data.preview;

    // Store preview type for footer rendering
    container.data('previewType', previewType);

    if (previewType === 'image' && preview) {
      // Image preview - full container size
      var imgContainer = $('<div>').addClass('image-preview-container').appendTo(container);
      var img = $('<img>')
        .attr('src', preview)
        .addClass('preview-image')
        .appendTo(imgContainer);

      // Store image reference for zoom controls
      container.data('previewImage', img);
      
      // Initialize image drag functionality
      FilePreviewDialog._initImageDrag(imgContainer);

    } else if (previewType === 'pdf') {
      // PDF preview using iframe with direct file endpoint
      var pdfContainer = $('<div>').addClass('pdf-preview-container').appendTo(container);

      // Build URL to file endpoint
      var pdfUrl = '/command/records-assets/file?root=' + encodeURIComponent(rootPath) +
                   '&path=' + encodeURIComponent(filePath);

      $('<iframe>')
        .attr('src', pdfUrl)
        .addClass('pdf-iframe')
        .appendTo(pdfContainer);

    } else if (previewType === 'text' && preview) {
      // Text preview
      var textContainer = $('<div>').addClass('text-preview-container').appendTo(container);
      $('<pre>')
        .addClass('text-preview')
        .text(preview)
        .appendTo(textContainer);

    } else {
      // Unknown type or no preview
      container.html(
        '<div class="no-preview">' +
        '<div class="file-icon">📄</div>' +
        '<div>' + ($.i18n('records.assets.preview.noPreview') || 'Cannot preview this file') + '</div>' +
        '</div>'
      );
    }
  };

  /**
   * Render footer with file info, zoom controls (for images), and actions
   */
  FilePreviewDialog._renderFooter = function(footer, data, rootPath, filePath) {
    footer.empty();

    // Left section: file info
    var info = $('<div>').addClass('file-info').appendTo(footer);

    if (data.size) {
      var sizeStr = FilePreviewDialog._formatFileSize(data.size);
      $('<span>').text(($.i18n('records.assets.list.size') || 'Size') + ': ' + sizeStr).appendTo(info);
    }

    if (data.mimeType) {
      $('<span>').text(' | ' + data.mimeType).appendTo(info);
    }

    // Action buttons container
    var actions = $('<div>').addClass('file-actions').appendTo(footer);

    // Zoom controls for images (in footer)
    var previewType = data.previewType || 'unknown';
    if (previewType === 'image') {
      var zoomControls = $('<div>').addClass('zoom-controls').appendTo(actions);

      $('<button>').addClass('button zoom-btn').text('−').on('click', function() {
        FilePreviewDialog._zoomLevel = Math.max(0.1, FilePreviewDialog._zoomLevel - 0.2);
        FilePreviewDialog._applyZoom();
      }).appendTo(zoomControls);

      $('<button>').addClass('button zoom-btn').text('100%').on('click', function() {
        FilePreviewDialog._zoomLevel = 1;
        FilePreviewDialog._currentOffsetX = 0;
        FilePreviewDialog._currentOffsetY = 0;
        FilePreviewDialog._applyZoom();
      }).appendTo(zoomControls);

      $('<button>').addClass('button zoom-btn').text('+').on('click', function() {
        FilePreviewDialog._zoomLevel = Math.min(5, FilePreviewDialog._zoomLevel + 0.2);
        FilePreviewDialog._applyZoom();
      }).appendTo(zoomControls);
    }

    // Download button
    $('<button>')
      .addClass('button')
      .text($.i18n('records.assets.preview.download') || 'Download')
      .on('click', function() {
        window.open('/command/records-assets/file?root=' + encodeURIComponent(rootPath) + '&path=' + encodeURIComponent(filePath) + '&download=true', '_blank');
      })
      .appendTo(actions);

    // Close button
    $('<button>')
      .addClass('button')
      .text($.i18n('core-buttons/close') || 'Close')
      .on('click', function() {
        FilePreviewDialog.close();
      })
      .appendTo(actions);
  };

  /**
   * Apply zoom level to preview image
   */
  FilePreviewDialog._applyZoom = function() {
    if (FilePreviewDialog._currentDialog) {
      var img = FilePreviewDialog._currentDialog.find('.preview-image');
      if (img.length) {
        img.css('transform', 'translate(' + FilePreviewDialog._currentOffsetX + 'px, ' + FilePreviewDialog._currentOffsetY + 'px) scale(' + FilePreviewDialog._zoomLevel + ')');
        img.css('transform-origin', 'top left');
        setTimeout(function() {
          FilePreviewDialog._renderAnnotations();
        }, 200);
      }
    }
  };

  /**
   * Initialize image drag functionality
   */
  FilePreviewDialog._initImageDrag = function(imgContainer) {
    var img = imgContainer.find('.preview-image');
    var content = FilePreviewDialog._currentDialog.find('.file-preview-float-content');
    
    var namespace = FilePreviewDialog._dragNamespace;
    
    img.on('mousedown' + namespace, function(e) {
      if (e.target.classList.contains('error-marker') || e.target.classList.contains('annotation-legend')) return;
      
      FilePreviewDialog._isDraggingImage = true;
      FilePreviewDialog._dragStartX = e.clientX;
      FilePreviewDialog._dragStartY = e.clientY;
      img.addClass('dragging');
      e.preventDefault();
    });
    
    $(document).on('mousemove' + namespace, function(e) {
      if (!FilePreviewDialog._isDraggingImage) return;
      
      var deltaX = e.clientX - FilePreviewDialog._dragStartX;
      var deltaY = e.clientY - FilePreviewDialog._dragStartY;
      
      FilePreviewDialog._currentOffsetX += deltaX;
      FilePreviewDialog._currentOffsetY += deltaY;
      
      FilePreviewDialog._dragStartX = e.clientX;
      FilePreviewDialog._dragStartY = e.clientY;
      
      FilePreviewDialog._applyZoom();
      e.preventDefault();
    });
    
    $(document).on('mouseup' + namespace, function() {
      if (FilePreviewDialog._isDraggingImage) {
        FilePreviewDialog._isDraggingImage = false;
        img.removeClass('dragging');
        FilePreviewDialog._renderAnnotations();
      }
    });
    
    // Clean up event listeners when dialog is removed
    imgContainer.on('remove', function() {
      $(document).off(namespace);
      img.off(namespace);
    });
    
    // Add mouse wheel zoom functionality
    imgContainer.on('wheel' + namespace, function(e) {
      e.preventDefault();
      
      var delta = e.originalEvent.deltaY;
      var zoomStep = delta > 0 ? -0.1 : 0.1;
      
      FilePreviewDialog._zoomLevel = Math.max(0.1, Math.min(5, FilePreviewDialog._zoomLevel + zoomStep));
      FilePreviewDialog._applyZoom();
    });
  };

  /**
   * Format file size to human readable string
   */
  FilePreviewDialog._formatFileSize = function(bytes) {
    if (bytes === 0) return '0 B';
    var k = 1024;
    var sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

})();



